// 그룹 순서대로 정렬 (같은 그룹 안에서는 원래 순서 유지)
{
  const order = TALK_GROUPS.map((g) => g.id);
  const sorted = [...TALK_TOPICS].sort((a, b) => order.indexOf(a.group) - order.indexOf(b.group));
  TALK_TOPICS.splice(0, TALK_TOPICS.length, ...sorted);
}

;

