// 변화 모양: AAA(셋 다 같음) · ABB(과거=과거분사) · ABA(원형=과거분사) · ABC(모두 다름)
const IRREGULAR_PATTERNS = [
  { id: "AAA", label: "A-A-A형", desc: "세 모양이 모두 같아요", example: "cut - cut - cut" },
  { id: "ABB", label: "A-B-B형", desc: "과거형과 과거분사가 같아요", example: "buy - bought - bought" },
  { id: "ABA", label: "A-B-A형", desc: "원형과 과거분사가 같아요", example: "come - came - come" },
  { id: "ABC", label: "A-B-C형", desc: "세 모양이 모두 달라요", example: "go - went - gone" },
  { id: "AAB", label: "A-A-B형", desc: "원형과 과거형이 같아요", example: "beat - beat - beaten" },
];

function irregularPattern(v) {
  if (v.base === v.past && v.past === v.pp) return "AAA";
  if (v.base === v.past) return "AAB";
  if (v.past === v.pp) return "ABB";
  if (v.base === v.pp) return "ABA";
  return "ABC";
}

;

