/* ── js/sound.js ── */
// 효과음은 파일 없이 Web Audio로 짧은 음을 만들어 낸다.
const SOUND_NOTES = {
  correct: { type: "triangle", notes: [660, 880], step: 0.09 },
  wrong: { type: "sine", notes: [262, 196], step: 0.13 },
  badge: { type: "triangle", notes: [523, 659, 784, 1047], step: 0.11 },
};

let audioContext = null;

// 휴대폰 진동: 정답은 짧게 한 번, 오답은 두 번. 기본은 꺼져 있고 설정에서 켠다.
const VIBRATE_PATTERNS = { correct: [30], wrong: [50, 60, 50], badge: [20, 40, 20, 40, 60] };

function vibrate(name) {
  if (!getSettings().vibrate || !navigator.vibrate) return;
  try {
    navigator.vibrate(VIBRATE_PATTERNS[name] || 0);
  } catch {
    // 진동을 못 해도 학습에는 영향 없음
  }
}

function playSound(name) {
  vibrate(name);
  if (!getSettings().sound) return;
  const AudioCtx = window.AudioContext || window.webkitAudioContext;
  if (!AudioCtx) return;
  try {
    audioContext ||= new AudioCtx();
    if (audioContext.state === "suspended") audioContext.resume();
    const { type, notes, step } = SOUND_NOTES[name];
    const start = audioContext.currentTime;
    notes.forEach((freq, i) => {
      const osc = audioContext.createOscillator();
      const gain = audioContext.createGain();
      const t = start + i * step;
      osc.type = type;
      osc.frequency.value = freq;
      gain.gain.setValueAtTime(0.0001, t);
      gain.gain.exponentialRampToValueAtTime(0.12, t + 0.015);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + step + 0.08);
      osc.connect(gain).connect(audioContext.destination);
      osc.start(t);
      osc.stop(t + step + 0.1);
    });
  } catch {
    // 소리를 못 내도 학습에는 영향 없음
  }
}

;

/* ── js/speech.js ── */
const speechSupported = "speechSynthesis" in window;

const cachedVoices = {};

function pickVoice(lang) {
  if (cachedVoices[lang] !== undefined) return cachedVoices[lang];
  const voices = window.speechSynthesis.getVoices();
  if (voices.length === 0) return null;
  const base = lang.slice(0, 2);
  cachedVoices[lang] =
    (lang === "en-US" && voices.find((v) => v.lang === "en-US" && /female/i.test(v.name))) ||
    voices.find((v) => v.lang === lang) ||
    voices.find((v) => v.lang && v.lang.startsWith(base)) ||
    null;
  return cachedVoices[lang];
}

if (speechSupported) {
  window.speechSynthesis.onvoiceschanged = () => {
    for (const key of Object.keys(cachedVoices)) delete cachedVoices[key];
  };
}

// 설정의 말하기 속도 (느리게 · 보통 · 빠르게)
const SPEECH_RATE_SCALE = { slow: 0.8, normal: 1, fast: 1.15 };
function speechRateScale() {
  return SPEECH_RATE_SCALE[getSettings().speechRate] || 1;
}

// 설정의 영어 목소리: 자동이면 기본 목소리, 여자 · 남자를 고르면 그 목소리(없으면 기본)
function preferredEnglishVoice() {
  const pref = getSettings().voice;
  if (pref === "female") return dialogVoice("W");
  if (pref === "male") return dialogVoice("M");
  return null;
}

// 안드로이드 크롬은 cancel() 직후 바로 speak()하면 소리 없이 버려지는 경우가 있고,
// 읽는 중인 문장 객체가 메모리에서 치워지면 소리가 끊기기도 한다. 그래서 읽던 게 있으면 잠깐 쉬었다가 읽고, 객체를 붙잡아 둔다.
let currentUtterance = null;
function startUtterance(utter) {
  const synth = window.speechSynthesis;
  const busy = synth.speaking || synth.pending;
  synth.cancel();
  currentUtterance = utter;
  const go = () => {
    if (currentUtterance !== utter) return; // 그사이 다른 소리를 눌렀으면 건너뛴다
    synth.resume(); // 멈춘 상태로 남아 있는 브라우저가 있어서 풀어 준다
    synth.speak(utter);
  };
  if (busy) setTimeout(go, 120);
  else go();
}

// onEnd는 끝까지 읽었을 때만 부른다 (중간에 다른 소리로 끊기면 부르지 않음). 읽을 문장 객체를 돌려준다.
function speak(text, { rate = 0.9, onEnd, lang = "en-US" } = {}) {
  if (!speechSupported || !text) return null;
  dialogToken += 1; // 대화를 읽던 중이면 멈춘다
  const utter = new SpeechSynthesisUtterance(text);
  utter.lang = lang;
  utter.rate = Math.min(2, rate * (lang.startsWith("en") ? speechRateScale() : 1));
  const voice = (lang.startsWith("en") && preferredEnglishVoice()) || pickVoice(lang);
  if (voice) utter.voice = voice;
  if (onEnd) utter.onend = onEnd;
  startUtterance(utter);
  return utter;
}

// 대화 읽기: 여자(W) · 남자(M)를 다른 목소리(없으면 다른 높이)로 차례로 읽는다.
function dialogVoice(speaker) {
  const en = window.speechSynthesis.getVoices().filter((v) => v.lang && v.lang.startsWith("en"));
  const female = /female|samantha|zira|aria|jenny|susan|karen|victoria|google us english/i;
  const male = /\bmale\b|david|guy|mark|daniel|alex|fred|george|ryan|google uk english male/i;
  if (speaker === "W") return en.find((v) => female.test(v.name)) || null;
  return en.find((v) => male.test(v.name) && !/female/i.test(v.name)) || null;
}

let dialogToken = 0;

function playDialog(lines, { rate = 0.9 } = {}) {
  if (!speechSupported || !lines?.length) return;
  const token = ++dialogToken;
  const sayLine = (i) => {
    if (i >= lines.length || token !== dialogToken) return;
    const [speaker, text] = lines[i];
    const utter = new SpeechSynthesisUtterance(text);
    utter.lang = "en-US";
    utter.rate = Math.min(2, rate * speechRateScale());
    const voice = dialogVoice(speaker) || pickVoice("en-US");
    if (voice) utter.voice = voice;
    const sameVoice = !dialogVoice("W") || !dialogVoice("M");
    utter.pitch = sameVoice ? (speaker === "W" ? 1.25 : 0.75) : 1;
    utter.onend = () => setTimeout(() => sayLine(i + 1), 350);
    startUtterance(utter);
  };
  sayLine(0);
}

// 한국어 설명 읽어 주기 (HTML 태그는 빼고 읽는다)
function speakKorean(html, options = {}) {
  speak(html.replace(/<[^>]+>/g, ""), { rate: 1, ...options, lang: "ko-KR" });
}

function stopSpeaking() {
  dialogToken += 1;
  currentUtterance = null;
  if (speechSupported) window.speechSynthesis.cancel();
}

;

/* ── js/confetti.js ── */
const COLORS = ["#ff8b3d", "#38b26b", "#4361ee", "#f4a300", "#8338ec", "#ff5c5c"];

function burstConfetti(count = 24) {
  const layer = document.createElement("div");
  layer.className = "confetti-layer";
  document.body.appendChild(layer);

  for (let i = 0; i < count; i++) {
    const piece = document.createElement("span");
    piece.className = "confetti-piece";
    piece.style.left = `${30 + Math.random() * 40}%`;
    piece.style.background = COLORS[Math.floor(Math.random() * COLORS.length)];
    piece.style.setProperty("--drift", `${(Math.random() - 0.5) * 200}px`);
    piece.style.setProperty("--rotate", `${Math.random() * 720 - 360}deg`);
    piece.style.animationDelay = `${Math.random() * 150}ms`;
    layer.appendChild(piece);
  }

  setTimeout(() => layer.remove(), 1300);
}

;

/* ── js/confirmModal.js ── */
function showConfirmModal({ message, confirmText = "확인", cancelText = "취소", onConfirm }) {
  document.querySelector(".modal-overlay")?.remove();
  const previousFocus = document.activeElement;

  const overlay = document.createElement("div");
  overlay.className = "modal-overlay";
  overlay.innerHTML = `
    <div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modalMessage">
      <p class="modal-message" id="modalMessage">${message}</p>
      <div class="modal-actions">
        <button class="secondary-btn" id="modalCancelBtn">${cancelText}</button>
        <button class="primary-btn modal-confirm-btn" id="modalConfirmBtn">${confirmText}</button>
      </div>
    </div>
  `;
  document.body.appendChild(overlay);

  const close = () => {
    overlay.remove();
    document.removeEventListener("keydown", onKey);
    previousFocus?.focus?.({ preventScroll: true });
  };
  const onKey = (e) => {
    if (e.key === "Escape") close();
  };
  document.addEventListener("keydown", onKey);

  overlay.addEventListener("click", (e) => {
    if (e.target === overlay) close();
  });
  overlay.querySelector("#modalCancelBtn").addEventListener("click", close);
  overlay.querySelector("#modalConfirmBtn").addEventListener("click", () => {
    close();
    onConfirm();
  });
  overlay.querySelector("#modalCancelBtn").focus();
}

;

/* ── js/ui.js ── */
// ── 글자 크기 (기기별 설정) ──
const TEXT_SCALE_KEY = "englishword:textScale";
const TEXT_SCALES = [
  { scale: 1, label: "보통" },
  { scale: 1.25, label: "크게" },
  { scale: 1.5, label: "아주 크게" },
];

function defaultTextScale() {
  return window.matchMedia("(min-width: 1024px)").matches ? 1.25 : 1;
}

function getTextScale() {
  try {
    const saved = Number(localStorage.getItem(TEXT_SCALE_KEY));
    if (TEXT_SCALES.some((t) => t.scale === saved)) return saved;
  } catch {
    // 저장소를 못 쓰면 기본값
  }
  return defaultTextScale();
}

function applyTextScale(scale) {
  document.documentElement.style.setProperty("--ui-scale", String(scale));
}

function textSizeControlHtml() {
  const current = getTextScale();
  return `
    <div class="text-size" role="group" aria-label="글자 크기">
      <span class="text-size-label">글자</span>
      ${TEXT_SCALES.map(
        (t, i) => `<button class="text-size-btn${t.scale === current ? " active" : ""}" data-scale="${t.scale}"
          aria-pressed="${t.scale === current}" aria-label="글자 ${t.label}" title="${t.label}" style="font-size:${13 + i * 4}px">가</button>`
      ).join("")}
    </div>
  `;
}

function bindTextSizeControl(root) {
  const buttons = root.querySelectorAll("[data-scale]");
  buttons.forEach((btn) => {
    btn.addEventListener("click", () => {
      const scale = Number(btn.dataset.scale);
      try {
        localStorage.setItem(TEXT_SCALE_KEY, String(scale));
      } catch {
        // 저장 실패해도 이번 화면에는 적용
      }
      applyTextScale(scale);
      buttons.forEach((b) => {
        const on = b === btn;
        b.classList.toggle("active", on);
        b.setAttribute("aria-pressed", String(on));
      });
    });
  });
}

// ── 테마 (auto | light | dark) ──
function applyTheme(theme) {
  if (theme === "light" || theme === "dark") document.documentElement.dataset.theme = theme;
  else delete document.documentElement.dataset.theme;
}

// ── 알림 토스트 ──
function showToast(html) {
  let stack = document.querySelector(".toast-stack");
  if (!stack) {
    stack = document.createElement("div");
    stack.className = "toast-stack";
    stack.setAttribute("aria-live", "polite");
    document.body.appendChild(stack);
  }
  const toast = document.createElement("div");
  toast.className = "toast";
  toast.innerHTML = html;
  stack.appendChild(toast);
  // 한꺼번에 여러 개가 뜨면 화면을 가리므로 최근 3개만 남긴다
  while (stack.children.length > 3) stack.firstElementChild.remove();
  setTimeout(() => toast.classList.add("toast--out"), 3200);
  setTimeout(() => toast.remove(), 3600);
}

function announceBadges(badges) {
  if (badges.length === 0) return;
  playSound("badge");
  if (badges.length > 2) {
    showToast(`<span class="toast-emoji">🏅</span><span><b>새 배지 ${badges.length}개!</b> ${badges.map((b) => b.emoji).join(" ")}<br><small>${badges.map((b) => b.title).join(" · ")}</small></span>`);
    return;
  }
  badges.forEach((b) => showToast(`<span class="toast-emoji">${b.emoji}</span><span><b>새 배지!</b> ${b.title}<br><small>${b.desc}</small></span>`));
}

// 정답이면 컨페티와 효과음, 오답이면 흔들기와 효과음.
function answerFeedback(isCorrect, wrongEl) {
  if (isCorrect) {
    burstConfetti();
    playSound("correct");
  } else {
    wrongEl?.classList.add("shake");
    playSound("wrong");
  }
}

// 긴 화면 맨 아래의 돌아가기 버튼. links: [{ label, onClick }]
function bottomNavHtml(links) {
  return `<nav class="bottom-nav" aria-label="돌아가기">${links.map((l, i) => `<button class="quick-link" data-bottom-nav="${i}">${l.label}</button>`).join("")}</nav>`;
}

function bindBottomNav(root, links) {
  root.querySelectorAll("[data-bottom-nav]").forEach((btn) => btn.addEventListener("click", links[Number(btn.dataset.bottomNav)].onClick));
}

// 여러 개 중 하나를 고르는 버튼 묶음 (data-<name> 속성으로 값 구분)
function segmentedHtml(name, options, current) {
  return `
    <div class="segmented" role="radiogroup">
      ${options.map((o) => `<button class="segmented-btn${o.id === current ? " active" : ""}" data-${name}="${o.id}" role="radio" aria-checked="${o.id === current}">${o.label}</button>`).join("")}
    </div>
  `;
}

function bindSegmented(root, name, onChange) {
  const buttons = root.querySelectorAll(`[data-${name}]`);
  buttons.forEach((btn) =>
    btn.addEventListener("click", () => {
      buttons.forEach((b) => {
        b.classList.toggle("active", b === btn);
        b.setAttribute("aria-checked", String(b === btn));
      });
      onChange(btn.dataset[name]);
    })
  );
}

function escapeRegExp(text) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function escapeHtml(text) {
  return String(text)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function levelById(levelId) {
  return LEVELS.find((lv) => lv.id === levelId) || null;
}

// 인쇄: 아이폰 홈 화면 앱에서는 window.print()가 동작하지 않아 사파리에서 열도록 안내한다
function printPage() {
  const ua = navigator.userAgent;
  const ios = /iPhone|iPad|iPod/.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1);
  const standalone = navigator.standalone || window.matchMedia?.("(display-mode: standalone)").matches;
  if (ios && standalone) {
    showToast(`<span class="toast-emoji">🖨️</span><span>아이폰 홈 화면 앱에서는 인쇄가 안 돼요. <b>사파리</b>에서 이 사이트를 열고 같은 화면에서 인쇄하거나, 공유 버튼 → <b>프린트</b>를 눌러 주세요.</span>`);
    return;
  }
  window.print();
}

function levelThemeStyle(level) {
  return level ? ` style="--primary:${level.color}; --primary-dark:${level.colorDark}"` : "";
}

function shortLevelLabel(level) {
  return level.label.split(" (")[0];
}

function withBlank(text, fill) {
  if (!text.includes("___")) return text;
  const inner = fill ? `<span class="blank blank-filled">${fill}</span>` : `<span class="blank"></span>`;
  return text.replace("___", inner);
}

function ratioLabel(best) {
  return best ? `${best.correct} / ${best.total}` : "도전 전";
}

function quizTopbarHtml({ label, index, total, scoreText, progressCount }) {
  return `
    <button class="quit-btn" id="quitQuizBtn">✕ 그만하기</button>
    <div class="quiz-topbar">
      <div class="progress">${label ? `${label} · ` : ""}${index + 1} / ${total}</div>
      <div class="score-live">${scoreText}</div>
    </div>
    <div class="progress-bar" role="progressbar" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${progressCount}">
      <div class="progress-bar-fill" style="width:${(progressCount / total) * 100}%"></div>
    </div>
  `;
}

function bindQuitConfirm(root, onConfirm) {
  root.querySelector("#quitQuizBtn")?.addEventListener("click", () => {
    showConfirmModal({
      message: "지금 그만두면 이번 기록은 저장되지 않아요. 그만할까요?",
      confirmText: "그만하기",
      cancelText: "계속 풀기",
      onConfirm,
    });
  });
}

