/* ── js/quiz.js ── */

const QUESTIONS_PER_GAME = 10;
const POINTS_PER_QUESTION = 10;

function shuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// 뜻 조각이 하나라도 같으면 보기로 같이 내지 않는다 (예: contest "대회" ↔ competition "대회/경쟁")
const meaningParts = (m) => String(m).replace(/\([^)]*\)/g, "").split(/[,/·;]/).map((s) => s.trim()).filter(Boolean);
function meaningsClash(a, b) {
  if (a === b) return true;
  const pa = meaningParts(a);
  return meaningParts(b).some((x) => pa.includes(x));
}

function toQuestion(wordData, pool, levelId) {
  const distractorPool = pool.filter((w) => w.id !== wordData.id && !meaningsClash(w.meaningKo, wordData.meaningKo) && w.word.toLowerCase() !== wordData.word.toLowerCase());
  const distractorWords = shuffle(distractorPool).slice(0, 3);
  const choiceMeta = shuffle([
    { word: wordData.word, meaningKo: wordData.meaningKo, isCorrect: true },
    ...distractorWords.map((w) => ({ word: w.word, meaningKo: w.meaningKo, isCorrect: false })),
  ]);
  const choices = choiceMeta.map((c) => c.word);

  return {
    data: wordData,
    levelId,
    choices,
    choiceMeta,
    correctAnswer: wordData.word,
    pictureHintUsed: false,
    descHintUsed: false,
    letterHintUsed: false,
    selectedAnswer: null,
  };
}

function letterHintPattern(word) {
  return word
    .split("")
    .map((ch, i) => (i === 0 ? ch : ch === " " ? " " : "_"))
    .join(" ");
}

function buildQuestions(levelId) {
  const pool = WORD_BANK[levelId] || [];
  const picked = shuffle(pool).slice(0, QUESTIONS_PER_GAME);
  return picked.map((wordData) => toQuestion(wordData, pool, levelId));
}

let wordIndex = null;

function getWordIndex() {
  if (wordIndex) return wordIndex;
  wordIndex = new Map();
  for (const level of LEVELS) {
    for (const wordData of WORD_BANK[level.id] || []) {
      wordIndex.set(wordData.id, wordData);
    }
  }
  return wordIndex;
}

function findWordById(id) {
  return getWordIndex().get(id) || null;
}

function buildReviewQuestions(wrongWordRefs) {
  const picked = shuffle(wrongWordRefs).slice(0, QUESTIONS_PER_GAME);
  return picked
    .map((ref) => {
      const wordData = findWordById(ref.id);
      if (!wordData) return null;
      const pool = WORD_BANK[ref.levelId] || [wordData];
      return toQuestion(wordData, pool, ref.levelId);
    })
    .filter(Boolean);
}

function scoreFromCorrectCount(correctCount) {
  return correctCount * POINTS_PER_QUESTION;
}

function normalizeTyped(text) {
  return text.toLowerCase().replace(/[’‘]/g, "'").replace(/\s+/g, " ").trim().replace(/[.!?,]+$/, "").trim();
}

function editDistance(a, b) {
  const dp = Array.from({ length: a.length + 1 }, (_, i) => [i, ...Array(b.length).fill(0)]);
  for (let j = 1; j <= b.length; j++) dp[0][j] = j;
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      dp[i][j] = Math.min(dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
    }
  }
  return dp[a.length][b.length];
}

// 단어 문제를 문법·독해와 같은 4지선다 형식으로 바꾼다 (오늘의 학습용).
function wordToMcQuestion(wordData, levelId) {
  const base = toQuestion(wordData, WORD_BANK[levelId] || [wordData], levelId);
  const ex = wordData.examples[0];
  return {
    id: wordData.id,
    kind: "word",
    levelId,
    label: "이 뜻을 가진 영어 단어는 무엇일까요?",
    q: wordData.meaningKo,
    big: true,
    ko: null,
    choices: base.choices,
    correctAnswer: wordData.word,
    explain: `<b>${wordData.word}</b> ${wordData.ipa} · ${wordData.meaningKo}<br>예) ${ex.en} — ${ex.ko}`,
    summary: `<b>${wordData.word}</b> · ${wordData.meaningKo}`,
    listenText: wordData.word,
    selectedAnswer: null,
  };
}

;

/* ── js/grammarQuiz.js ── */
const GRAMMAR_REVIEW_LIMIT = 10;

function findGrammarTopic(topicId) {
  return GRAMMAR_TOPICS.find((t) => t.id === topicId) || null;
}

function toGrammarQuestion(topic, index) {
  const raw = topic.questions[index];
  const correctAnswer = raw.choices[raw.answer];
  const hasBlank = raw.q.includes("___");
  return {
    id: `${topic.id}-${index}`,
    kind: "grammar",
    topicId: topic.id,
    label: "빈칸이나 질문에 알맞은 답을 고르세요",
    q: raw.q,
    ko: raw.ko || null,
    choices: shuffle(raw.choices),
    correctAnswer,
    explain: raw.explain,
    summary: withBlank(raw.q, correctAnswer),
    listenText: hasBlank ? raw.q.replace("___", correctAnswer) : null,
    selectedAnswer: null,
  };
}

function buildGrammarQuestions(topicId) {
  const topic = findGrammarTopic(topicId);
  if (!topic) return [];
  return shuffle(topic.questions.map((_, i) => toGrammarQuestion(topic, i)));
}

function grammarQuestionById(id) {
  const cut = id.lastIndexOf("-");
  const topic = findGrammarTopic(id.slice(0, cut));
  const index = Number(id.slice(cut + 1));
  return topic && topic.questions[index] ? toGrammarQuestion(topic, index) : null;
}

function buildGrammarReviewQuestions(questionIds) {
  return shuffle(questionIds).slice(0, GRAMMAR_REVIEW_LIMIT).map(grammarQuestionById).filter(Boolean);
}

function buildReadingQuestions(passage) {
  return passage.questions.map((raw, i) => ({
    id: `${passage.id}-${i}`,
    kind: "reading",
    label: "지문을 읽고 알맞은 답을 고르세요",
    q: raw.q,
    ko: null,
    choices: shuffle(raw.choices),
    correctAnswer: raw.choices[raw.answer],
    explain: raw.explain,
    summary: raw.q,
    listenText: null,
    selectedAnswer: null,
  }));
}

const DAILY_WORDS = 4;
const DAILY_EXTRA = 1; // 숫자 읽기 · 소리 구별 문제 (날마다 번갈아)
const DAILY_GRAMMAR = 3;

// 짝수 날은 내 단계에 맞는 숫자 · 시간 · 날짜 · 돈 읽기, 홀수 날은 비슷한 소리 구별
function dailyExtraQuestions(levelId, count) {
  const day = new Date().getDate();
  if (day % 2 === 0) {
    const mine = NUMBER_SETS.filter((s) => s.levelId === levelId);
    const sets = mine.length ? mine : NUMBER_SETS.filter((s) => ["date", "money", "big"].includes(s.id));
    return Array.from({ length: count }, (_, i) => numberQuestion(sets[(day / 2 + i) % sets.length], day + i));
  }
  return buildSoundQuestions("all").slice(0, count);
}

// 오늘의 학습: 단어 4문제 + 숫자 · 소리 1문제 + 문법 3문제.
// 단어는 복습할 때가 된 오답(틀린 다음 날, 맞힌 뒤 3일) → 단어장 오늘 복습 → 내 단계의 새 단어 순서로 채운다.
function buildDailyQuestions(profileName) {
  const levelId = getPreferredLevel(profileName) || getLastWordLevel(profileName) || LEVELS[0].id;
  const vocab = getVocabEntries(profileName);
  const picked = [];
  const used = new Set();
  const take = (id, wordLevelId, review = false) => {
    if (picked.length >= DAILY_WORDS || used.has(id) || !findWordById(id)) return;
    used.add(id);
    const q = wordToMcQuestion(findWordById(id), wordLevelId);
    if (review) q.label = `🔁 지난번에 틀린 단어 · ${q.label}`;
    picked.push(q);
  };
  getDueWrongs(profileName).words.slice(0, 2).forEach((ref) => take(ref.id, ref.levelId, true));
  shuffle(getDueVocabIds(profileName)).forEach((id) => take(id, vocab[id].levelId));
  shuffle(WORD_BANK[levelId]).forEach((w) => take(w.id, levelId));
  // 문법은 내 단계에 맞춰 기초 문법 · 불규칙 동사 · to/-ing · 독해 문법에서 고른다 (js/drill.js).
  return shuffle([...picked, ...dailyExtraQuestions(levelId, DAILY_EXTRA), ...buildDailyGrammarQuestions(profileName, levelId, DAILY_GRAMMAR)]);
}

;

/* ── js/drill.js ── */
// 연습 문제(기초 문법 · 불규칙 동사 · to/-ing)를 id로 다시 만들기, 오답 복습, 오늘의 학습용 단계 맞춤 문제.
// id 형식: "basic|주제id|문제번호" · "irr|세트id|원형|past|pp|base" · "vp|b|동사|정답" · "vp|k|동사"
const DRILL_REVIEW_LIMIT = 10;

function basicChooseQuestion(topic, index) {
  const raw = topic.practice[index];
  if (!raw || raw.type !== "choose") return null;
  const correctAnswer = raw.choices[raw.answer];
  return {
    id: `basic|${topic.id}|${index}`,
    drill: true,
    kind: "basic",
    label: "빈칸에 알맞은 답을 고르세요",
    q: raw.q,
    ko: raw.ko || null,
    choices: shuffle(raw.choices),
    correctAnswer,
    explain: `${topic.emoji} ${topic.title}: ${raw.hint}`,
    summary: withBlank(raw.q, correctAnswer),
    listenText: raw.q.includes("___") ? raw.q.replace("___", correctAnswer) : null,
    selectedAnswer: null,
  };
}

function drillQuestionById(id) {
  const [type, a, b, c] = id.split("|");
  if (type === "basic") {
    const topic = findBasicTopic(a);
    return topic ? basicChooseQuestion(topic, Number(b)) : null;
  }
  if (type === "irr") {
    if (!["past", "pp", "base"].includes(c)) return null;
    const set = findIrregularSet(a);
    const v = set?.verbs.find((x) => x.base === b);
    return v ? irregularQuestion(v, set, c) : null;
  }
  if (type === "vp") {
    for (const g of VERB_PATTERN_GROUPS) {
      const v = g.verbs.find((x) => x.v === b);
      if (!v) continue;
      if (a === "k") return vpKindQuestion({ g, v, item: v.items[0] });
      const item = v.items.find((it) => it.form === c);
      return item ? vpBlankQuestion({ g, v, item }) : null;
    }
  }
  return null;
}

// 오답노트에 보여 줄 출처
function drillSourceLabel(id) {
  const [type, a] = id.split("|");
  if (type === "basic") {
    const topic = findBasicTopic(a);
    return topic ? `${topic.emoji} ${topic.title}` : "";
  }
  if (type === "irr") return "🔁 불규칙 동사";
  return "🔀 to부정사 · 동명사";
}

function buildDrillReviewQuestions(profileName) {
  return shuffle(getDrillWrongEntries(profileName).map((e) => e.id))
    .slice(0, DRILL_REVIEW_LIMIT)
    .map(drillQuestionById)
    .filter(Boolean);
}

function levelRank(levelId) {
  return LEVELS.findIndex((lv) => lv.id === levelId);
}

// 내 단계의 기초 문법 주제 중 끝낸 것 + 학년마다 다음 한 주제
function openBasicTopicsFor(profileName, levelId) {
  const grades = BASIC_GRADES.filter((g) => g.levelId === levelId).map((g) => g.id);
  const open = [];
  for (const grade of grades) {
    const topics = BASIC_TOPICS.filter((t) => t.grade === grade);
    const firstTodo = topics.findIndex((t) => !getSectionBest(profileName, "basics", t.id));
    open.push(...topics.slice(0, firstTodo === -1 ? topics.length : firstTodo + 1));
  }
  return open;
}

// 오늘의 학습 문법 문제: 연습 오답 → 문법 오답 → 내 단계에 맞는 새 문제(여러 종류를 돌아가며)
function buildDailyGrammarQuestions(profileName, levelId, count) {
  const rank = Math.max(0, levelRank(levelId));
  const picked = [];
  const used = new Set();
  const add = (q) => {
    if (!q || picked.length >= count || used.has(q.id)) return;
    used.add(q.id);
    picked.push(q);
  };

  // 복습할 때가 된 오답을 먼저 (최대 2개, 새 문제가 하나는 남도록)
  const due = getDueWrongs(profileName);
  const dueQs = [...due.drill.map((e) => drillQuestionById(e.id)), ...(rank >= levelRank("middle") ? due.grammar.map((e) => grammarQuestionById(e.id)) : [])].filter(Boolean);
  dueQs.slice(0, Math.min(2, count - 1)).forEach((q) => add({ ...q, label: `🔁 지난번에 틀린 문제 · ${q.label}` }));

  const pools = [];
  const basicPool = openBasicTopicsFor(profileName, levelId).flatMap((t) => t.practice.map((_, i) => () => basicChooseQuestion(t, i)));
  if (basicPool.length) pools.push(shuffle(basicPool));
  if (rank >= levelRank("elementary-mid")) {
    const sets = IRREGULAR_SETS.filter((s) => levelRank(s.levelId) <= rank);
    pools.push(shuffle(sets.flatMap((s) => s.verbs.map((v) => () => irregularQuestion(v, s, ["past", "pp"][Math.floor(Math.random() * 2)])))));
  }
  if (rank >= levelRank("middle")) {
    pools.push(shuffle(vpEntries(["to-only", "ing-only", "both-diff"]).map((e) => () => vpBlankQuestion(e))));
    const doneUntil = GRAMMAR_TOPICS.findIndex((t) => !getSectionBest(profileName, "grammar", t.id));
    const openTopics = GRAMMAR_TOPICS.slice(0, doneUntil === -1 ? GRAMMAR_TOPICS.length : doneUntil + 1);
    pools.push(shuffle(openTopics.flatMap((t) => t.questions.map((_, i) => () => grammarQuestionById(`${t.id}-${i}`)))));
  }
  const order = shuffle(pools.filter((p) => p.length));
  for (let round = 0; picked.length < count && order.some((p) => p.length); round++) {
    for (const pool of order) {
      // choose가 아닌 문제(순서 맞추기)는 건너뛴다
      while (pool.length && picked.length < count) {
        const q = pool.shift()();
        if (q && !used.has(q.id)) {
          add(q);
          break;
        }
      }
    }
  }
  return picked;
}

;

/* ── js/nextStep.js ── */
// "이어서 하기": 내 단계에서 아직 안 끝낸 다음 공부를 하나 골라 홈 맨 위에 보여 준다.
// 목록 화면에서는 내 단계를 먼저 펼치고, 다른 단계는 접어 둔다.
const TALK_GROUP_LEVELS = {
  hello: ["elementary-low", "elementary-mid"],
  daily: ["elementary-mid", "elementary-high"],
  out: ["elementary-mid", "elementary-high"],
  middle: ["middle"],
  high: ["high"],
  adult: ["adult"],
};

function myLevelOf(profileName) {
  return getPreferredLevel(profileName) || getLastWordLevel(profileName) || null;
}

function nextStep(profileName) {
  const level = getPreferredLevel(profileName);
  if (!level) return { emoji: "🧭", title: "내 단계 정하기", desc: "설정에서 단계를 고르면 맞춤 공부를 이어서 추천해요", type: "settings" };
  const done = (section, id) => !!getSectionBest(profileName, section, id);
  const passedBest = (section, id) => {
    const b = getSectionBest(profileName, section, id);
    return b && b.correct / b.total >= 0.8;
  };

  for (const g of BASIC_GRADES.filter((x) => x.levelId === level)) {
    const t = BASIC_TOPICS.find((x) => x.grade === g.id && !done("basics", x.id));
    if (t) return { emoji: t.emoji, title: `${g.label.replace(/^\S+\s/, "")} · ${t.title}`, desc: t.subtitle, type: "lesson", id: t.id };
  }
  const talk = TALK_TOPICS.find((t) => TALK_GROUP_LEVELS[t.group]?.includes(level) && !done("basics", t.id));
  if (talk) return { emoji: talk.emoji, title: `대화 표현 · ${talk.title}`, desc: talk.subtitle, type: "lesson", id: talk.id };
  const irr = IRREGULAR_SETS.find((s) => s.levelId === level && !passedBest("irregular", s.id));
  if (irr) return { emoji: "🔁", title: `불규칙 동사 · ${irr.title}`, desc: "변화표를 보고 테스트 80점 넘기기", type: "screen", screen: "irregular" };
  if (!passedBest("listening", level) && LISTENING_SETS.some((s) => s.levelId === level)) {
    return { emoji: "🎧", title: "듣기 평가", desc: `${levelById(level).label} 대화 5개`, type: "listening", id: level };
  }
  const exam = BASIC_GRADES.find((g) => g.levelId === level && !passedBest("exam", g.id));
  if (exam) return { emoji: "📝", title: `단원 모의고사 · ${exam.label.replace(/^\S+\s/, "")}`, desc: "20문제 · 80점 넘기기", type: "exam", id: exam.id };
  return { emoji: "🧩", title: "가로세로 낱말", desc: "내 단계를 다 끝냈어요! 퍼즐로 단어를 다져요", type: "crossword", id: level };
}

// 내 단계 진행률: 문법 · 대화 · 읽기 · 듣기 · 단어 각각의 진행 비율을 평균 낸다.
function levelProgress(profileName) {
  const levelId = getPreferredLevel(profileName);
  if (!levelId) return null;
  const level = levelById(levelId);
  const best = (section, id) => getSectionBest(profileName, section, id);
  const grades = BASIC_GRADES.filter((g) => g.levelId === levelId).map((g) => g.id);
  const basics = BASIC_TOPICS.filter((t) => grades.includes(t.grade));
  const talks = TALK_TOPICS.filter((t) => TALK_GROUP_LEVELS[t.group]?.includes(levelId));
  const passages = READING_PASSAGES.filter((p) => p.levelId === levelId);
  const listening = LISTENING_SETS.find((s) => s.levelId === levelId);
  const words = WORD_BANK[levelId] || [];
  const vocab = getVocabEntries(profileName);
  const listenBest = best("listening", levelId);
  const parts = [
    basics.length && { label: "문법", done: basics.filter((t) => best("basics", t.id)).length, total: basics.length },
    talks.length && { label: "대화", done: talks.filter((t) => best("basics", t.id)).length, total: talks.length },
    passages.length && { label: "읽기", done: passages.filter((p) => best("reading", p.id) || isPassageRead(profileName, p.id)).length, total: passages.length },
    listening && { label: "듣기", done: listenBest ? Math.round((listenBest.correct / listenBest.total) * 5) : 0, total: 5 },
    words.length && { label: "단어", done: words.filter((w) => vocab[w.id]).length, total: words.length },
  ].filter(Boolean);
  const percent = parts.length ? Math.round((parts.reduce((sum, p) => sum + p.done / p.total, 0) / parts.length) * 100) : 0;
  return { level, percent, parts };
}

// 목록을 내 단계 / 다른 단계로 나눈다. levelsOf(item) → 그 항목이 속한 단계 id 배열
function splitByMyLevel(items, levelsOf, myLevel) {
  if (!myLevel) return { mine: items, others: [] };
  const mine = items.filter((it) => levelsOf(it).includes(myLevel));
  return mine.length ? { mine, others: items.filter((it) => !mine.includes(it)) } : { mine: items, others: [] };
}

// 내 단계 카드는 그대로, 다른 단계는 접어서 보여 준다
function levelSplitHtml(mineHtml, othersHtml, othersCount) {
  return `
    <div class="level-grid">${mineHtml}</div>
    ${
      othersCount
        ? `<details class="other-levels">
        <summary class="basic-grade-title">다른 단계 보기 <span class="basic-grade-count">${othersCount}</span></summary>
        <div class="level-grid">${othersHtml}</div>
      </details>`
        : ""
    }`;
}

;

/* ── js/vocab.js ── */
const VOCAB_SESSION_SIZE = 10;
const VOCAB_REVIEW_LIMIT = 20;

// 단어장 카드 한 장. 기본 단어장 단어와 지문에서 추가한 단어를 같은 모양으로 맞춘다.
function vocabCard(profileName, id) {
  const bank = findWordById(id);
  if (bank) {
    const levelId = LEVELS.find((lv) => (WORD_BANK[lv.id] || []).includes(bank))?.id;
    return { ...bank, levelId, custom: false };
  }
  const custom = getCustomWords(profileName)[id];
  if (!custom) return null;
  return {
    id,
    word: custom.word,
    ipa: "",
    meaningKo: custom.meaningKo,
    emoji: "📖",
    desc: custom.sourceTitle ? `'${custom.sourceTitle}' 지문에서 추가한 단어예요.` : "",
    examples: custom.sentence ? [{ en: custom.sentence, ko: custom.sentenceKo || "" }] : [],
    levelId: custom.levelId,
    custom: true,
  };
}

// source: { type: "review" } | { type: "level", levelId } | { type: "starred" }
function buildVocabSession(profileName, source) {
  const entries = getVocabEntries(profileName);
  const today = dateKey();
  let ids;
  if (source.type === "review") {
    ids = shuffle(getDueVocabIds(profileName)).slice(0, VOCAB_REVIEW_LIMIT);
  } else if (source.type === "starred") {
    ids = shuffle(getStarredIds(profileName)).slice(0, VOCAB_REVIEW_LIMIT);
  } else {
    const pool = WORD_BANK[source.levelId] || [];
    const due = shuffle(pool.filter((w) => entries[w.id] && entries[w.id].due <= today).map((w) => w.id));
    const fresh = shuffle(pool.filter((w) => !entries[w.id]).map((w) => w.id));
    ids = [...due, ...fresh].slice(0, VOCAB_SESSION_SIZE);
  }
  return ids.map((id) => vocabCard(profileName, id)).filter(Boolean);
}

function vocabBoxLabel(entry) {
  if (!entry) return { label: "새 단어", cls: "new" };
  if (entry.box >= VOCAB_MASTERED_BOX) return { label: "외웠어요", cls: "mastered" };
  if (entry.box === 0) return { label: "헷갈려요", cls: "unsure" };
  return { label: "익히는 중", cls: "learning" };
}

function vocabSessionTitle(source) {
  if (source.type === "review") return "🔁 오늘의 복습";
  if (source.type === "starred") return "⭐ 즐겨찾기";
  const level = levelById(source.levelId);
  return `${level.emoji} ${shortLevelLabel(level)}`;
}

// 지문의 단어를 단어장에 넣는다. 기본 단어장에 같은 단어가 있으면 그 단어(발음·예문 포함)를 쓴다.
function addGlossToVocab(profileName, passage, glossIndex) {
  const g = passage.glossary[glossIndex];
  const lower = g.w.toLowerCase();
  for (const level of LEVELS) {
    const match = (WORD_BANK[level.id] || []).find((w) => w.word.toLowerCase() === lower);
    if (match) {
      const entry = getVocabEntries(profileName)[match.id];
      if (!entry) recordVocabReview(profileName, match.id, level.id, false);
      return { id: match.id, word: match.word };
    }
  }
  const sentence = passage.sentences.find((s) => new RegExp(`\\b${escapeRegExp(g.w)}\\b`, "i").test(s.en));
  const id = `c:${passage.id}:${glossIndex}`;
  addCustomWord(profileName, {
    id,
    word: g.w,
    meaningKo: g.ko,
    sentence: sentence?.en || "",
    sentenceKo: sentence?.ko || "",
    levelId: passage.levelId,
    sourceTitle: passage.title,
  });
  return { id, word: g.w };
}

function isGlossInVocab(profileName, passage, glossIndex) {
  const g = passage.glossary[glossIndex];
  const entries = getVocabEntries(profileName);
  if (entries[`c:${passage.id}:${glossIndex}`]) return true;
  const lower = g.w.toLowerCase();
  return LEVELS.some((lv) => (WORD_BANK[lv.id] || []).some((w) => w.word.toLowerCase() === lower && entries[w.id]));
}

;

/* ── js/pwa.js ── */
let deferredInstallPrompt = null;

window.addEventListener("beforeinstallprompt", (event) => {
  event.preventDefault();
  deferredInstallPrompt = event;
  document.dispatchEvent(new Event("pwa-install-change"));
});

window.addEventListener("appinstalled", () => {
  deferredInstallPrompt = null;
  document.dispatchEvent(new Event("pwa-install-change"));
  showToast(`<span class="toast-emoji">📲</span><span>홈 화면에 앱을 설치했어요</span>`);
});

// 새 버전의 서비스 워커가 이 페이지를 넘겨받으면 true. app.js가 안전한 화면에서 새로고침한다.
let appUpdateReady = false;

function registerServiceWorker() {
  // 서비스 워커는 http(s)에서만 동작한다. 파일로 연 경우(file://)는 건너뛴다.
  if (!("serviceWorker" in navigator) || !location.protocol.startsWith("http")) return;
  const hadController = !!navigator.serviceWorker.controller;

  navigator.serviceWorker
    .register("sw.js")
    .then((reg) => {
      // 휴대폰 앱은 닫아도 메모리에 남아 이어서 열리므로, 다시 볼 때마다 새 버전을 확인한다.
      document.addEventListener("visibilitychange", () => {
        if (document.visibilityState === "visible") reg.update().catch(() => {});
      });
    })
    .catch(() => {});

  navigator.serviceWorker.addEventListener("controllerchange", () => {
    // 처음 설치할 때도 이 이벤트가 오지만, 그때는 이미 최신이라 새로고침할 필요가 없다.
    if (!hadController || appUpdateReady) return;
    appUpdateReady = true;
    document.dispatchEvent(new Event("pwa-update-ready"));
  });
}

function isStandalone() {
  return window.matchMedia("(display-mode: standalone)").matches || navigator.standalone === true;
}

function isIos() {
  return /iphone|ipad|ipod/i.test(navigator.userAgent) || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
}

// installed | prompt | ios | file | manual
function installState() {
  if (isStandalone()) return "installed";
  if (!location.protocol.startsWith("http")) return "file";
  if (deferredInstallPrompt) return "prompt";
  if (isIos()) return "ios";
  return "manual";
}

function installGuideHtml() {
  switch (installState()) {
    case "installed":
      return `<p class="settings-help">✅ 지금 앱으로 실행 중이에요.</p>`;
    case "prompt":
      return `<button class="primary-btn" data-install>📲 홈 화면에 앱 설치</button>`;
    case "ios":
      return `<p class="settings-help install-steps">Safari 아래쪽의 <b>공유 버튼(⬆️)</b>을 누르고 <b>'홈 화면에 추가'</b>를 고르세요.</p>`;
    case "file":
      return `<p class="settings-help">파일로 열면 설치할 수 없어요. 웹 주소(https://…)로 열면 설치할 수 있어요.</p>`;
    default:
      return `<p class="settings-help">브라우저 메뉴(⋮)에서 <b>'앱 설치'</b> 또는 <b>'홈 화면에 추가'</b>를 고르세요.</p>`;
  }
}

// container 안의 설치 안내를 그리고, 설치 가능 상태가 바뀌면 다시 그린다.
// onlyWhenOffered면 바로 설치할 수 있을 때(설치 버튼·아이폰 안내)만 보여 준다.
function mountInstallGuide(container, { onlyWhenOffered = false } = {}) {
  const draw = () => {
    if (!container.isConnected) {
      document.removeEventListener("pwa-install-change", draw);
      return;
    }
    const show = !onlyWhenOffered || canOfferInstall();
    container.hidden = !show;
    container.innerHTML = show ? installGuideHtml() : "";
    container.querySelector("[data-install]")?.addEventListener("click", async () => {
      if (!deferredInstallPrompt) return;
      deferredInstallPrompt.prompt();
      await deferredInstallPrompt.userChoice;
      deferredInstallPrompt = null;
      draw();
    });
  };
  document.addEventListener("pwa-install-change", draw);
  draw();
}

function canOfferInstall() {
  const state = installState();
  return state === "prompt" || state === "ios";
}

;

