/* ── js/screens/level.js ── */
// 단어 시험: 고르기 · 철자 쓰기 · 받아쓰기를 한 화면에서 골라 푼다.
function renderLevelScreen(root, { profileName, wordMode, selectLevel, backToHome, startReview, setMode }) {
  const wrongWordCount = getWrongWords(profileName).length;
  const info = WORD_MODES[wordMode];
  const preferred = getPreferredLevel(profileName);
  const modes = Object.entries(WORD_MODES).filter(([id]) => id !== "dictation" || speechSupported);

  root.innerHTML = `
    <div class="screen screen-level">
      <button class="back-btn" id="backBtn">← 홈</button>
      <h1 class="title">✏️ 단어 시험</h1>
      <div class="segmented segmented--wide" role="tablist" aria-label="시험 방식">
        ${modes.map(([id, m]) => `<button class="segmented-btn${id === wordMode ? " active" : ""}" data-mode="${id}" role="tab" aria-selected="${id === wordMode}">${m.emoji} ${m.title}</button>`).join("")}
      </div>
      <p class="subtitle">${info.desc} · 단계를 고르면 10문제가 나와요</p>

      ${wrongWordCount > 0 ? `
        <button class="review-card" id="reviewBtn">
          <span class="review-emoji">📝</span>
          <span class="review-text">
            <span class="review-title">오답노트 복습</span>
            <span class="review-desc">틀렸던 단어 ${wrongWordCount}개를 ${info.title} 방식으로 다시 풀어봐요</span>
          </span>
        </button>
      ` : ""}

      <div class="level-grid">
        ${LEVELS.map((lv) => {
          const best = getBestScore(profileName, lv.id, wordMode);
          return `
            <button class="level-card" data-id="${lv.id}" style="--accent:${lv.color}">
              <span class="level-icon">${lv.emoji}</span>
              <span class="topic-text">
                <span class="level-label">${lv.label}</span>
                ${lv.id === preferred ? `<span class="topic-level">⭐ 내 단계</span>` : ""}
              </span>
              ${best !== null ? `<span class="level-best">최고 ${best}점</span>` : `<span class="level-best level-best-empty">기록 없음</span>`}
            </button>
          `;
        }).join("")}
      </div>
    </div>
  `;

  root.querySelector("#backBtn").addEventListener("click", backToHome);
  root.querySelectorAll("[data-mode]").forEach((b) => b.addEventListener("click", () => setMode(b.dataset.mode)));
  root.querySelector("#reviewBtn")?.addEventListener("click", startReview);
  root.querySelectorAll(".level-card").forEach((btn) => {
    btn.addEventListener("click", () => selectLevel(btn.dataset.id));
  });
}

;

/* ── js/screens/quizScreen.js ── */

const ANSWER_REVEAL_DELAY_MS = 700;

function themeStyle(ctx) {
  if (!ctx.levelColor) return "";
  return ` style="--primary:${ctx.levelColor}; --primary-dark:${ctx.levelColorDark || ctx.levelColor}"`;
}

function bindQuitButton(root, actions) {
  bindQuitConfirm(root, actions.quitQuiz);
}

function choiceTopbar(ctx, progressCount) {
  return quizTopbarHtml({ label: "📚 단어 퀴즈", index: ctx.index, total: ctx.total, scoreText: `점수 ${ctx.score}점`, progressCount });
}

function renderQuestionPhase(root, ctx) {
  const { question, index, actions } = ctx;
  const { data } = question;

  root.innerHTML = `
    <div class="screen screen-quiz"${themeStyle(ctx)}>
      ${choiceTopbar(ctx, index)}

      <div class="question-card">
        <p class="question-label">이 뜻을 가진 영어 단어는 무엇일까요?</p>
        <p class="question-meaning">${data.meaningKo}</p>
      </div>

      <div class="hint-row">
        <button class="hint-btn" id="pictureHintBtn" ${question.pictureHintUsed ? "disabled" : ""}>
          🖼 그림${question.pictureHintUsed ? " ✓" : ""}
        </button>
        <button class="hint-btn" id="descHintBtn" ${question.descHintUsed ? "disabled" : ""}>
          💬 설명${question.descHintUsed ? " ✓" : ""}
        </button>
        <button class="hint-btn" id="letterHintBtn" ${question.letterHintUsed ? "disabled" : ""}>
          🔤 글자${question.letterHintUsed ? " ✓" : ""}
        </button>
      </div>
      <div class="hint-reveal" id="hintReveal">
        ${question.pictureHintUsed ? `<div class="hint-item hint-picture">${data.emoji}</div>` : ""}
        ${question.descHintUsed ? `<div class="hint-item hint-desc">${data.desc}</div>` : ""}
        ${question.letterHintUsed ? `<div class="hint-item hint-letter">${letterHintPattern(data.word)}</div>` : ""}
      </div>

      <div class="choice-grid">
        ${question.choices
          .map((choice) => `<button class="choice-btn" data-choice="${choice}">${choice}</button>`)
          .join("")}
      </div>
    </div>
  `;

  bindQuitButton(root, actions);
  root.querySelector("#pictureHintBtn").addEventListener("click", () => actions.useHint("picture"));
  root.querySelector("#descHintBtn").addEventListener("click", () => actions.useHint("desc"));
  root.querySelector("#letterHintBtn").addEventListener("click", () => actions.useHint("letter"));

  let answered = false;
  root.querySelectorAll(".choice-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (answered) return;
      answered = true;
      const choice = btn.dataset.choice;
      const isCorrect = choice === question.correctAnswer;

      root.querySelectorAll(".choice-btn").forEach((b) => {
        b.disabled = true;
        if (b.dataset.choice === question.correctAnswer) b.classList.add("correct");
        else if (b === btn) b.classList.add("wrong");
      });

      answerFeedback(isCorrect, btn);

      setTimeout(() => actions.selectAnswer(choice), ANSWER_REVEAL_DELAY_MS);
    });
  });
}

function renderDetailPhase(root, ctx) {
  const { question, index, total, actions } = ctx;
  const { data } = question;
  const isCorrect = question.selectedAnswer === question.correctAnswer;
  const isLast = index === total - 1;

  root.innerHTML = `
    <div class="screen screen-quiz"${themeStyle(ctx)}>
      ${choiceTopbar(ctx, index + 1)}

      <div class="result-banner ${isCorrect ? "correct" : "wrong"}" role="status">
        ${isCorrect ? "🎉 정답이에요!" : `❌ 아쉬워요! 정답은 ${data.word} 였어요`}
      </div>

      <div class="choice-explain">
        <p class="choice-explain-title">왜 정답/오답일까요?</p>
        ${question.choiceMeta
          .map((c) => {
            const wasMyPick = c.word === question.selectedAnswer;
            return `
            <div class="choice-explain-row ${c.isCorrect ? "correct" : "wrong"}${wasMyPick ? " mine" : ""}">
              <span class="choice-explain-mark">${c.isCorrect ? "✅" : "❌"}</span>
              <span class="choice-explain-word">${c.word}</span>
              <span class="choice-explain-meaning">${c.meaningKo}</span>
              ${c.isCorrect ? `<span class="choice-explain-tag">정답</span>` : wasMyPick ? `<span class="choice-explain-tag choice-explain-tag--mine">내가 고른 답</span>` : ""}
            </div>
          `;
          })
          .join("")}
      </div>

      <div class="word-detail-card">
        <div class="word-line">
          <span class="word-text">${data.word}</span>
          <button class="speak-btn" id="speakWordBtn" ${speechSupported ? "" : "disabled"}>🔊</button>
          <span class="ipa-text">${data.ipa}</span>
        </div>
        <div class="meaning-text">${data.meaningKo}</div>

        <div class="examples">
          <p class="examples-title">예문으로 익혀봐요</p>
          ${data.examples
            .map(
              (ex, i) => `
            <div class="example-item">
              <div class="example-en">
                <button class="speak-btn" data-example-index="${i}" ${speechSupported ? "" : "disabled"}>🔊</button>
                <span>${ex.en}</span>
              </div>
              <button class="example-toggle" data-toggle-index="${i}">뜻 보기</button>
              <div class="example-ko" id="exampleKo${i}" hidden>${ex.ko}</div>
            </div>
          `
            )
            .join("")}
        </div>
      </div>

      <button class="primary-btn" id="nextBtn">${isLast ? "결과 보기" : "다음 문제"}</button>
    </div>
  `;

  bindQuitButton(root, actions);
  root.querySelector("#speakWordBtn")?.addEventListener("click", () => speak(data.word));
  root.querySelectorAll("[data-example-index]").forEach((btn) => {
    btn.addEventListener("click", () => speak(data.examples[Number(btn.dataset.exampleIndex)].en));
  });
  root.querySelectorAll("[data-toggle-index]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const el = root.querySelector(`#exampleKo${btn.dataset.toggleIndex}`);
      el.hidden = !el.hidden;
      btn.textContent = el.hidden ? "뜻 보기" : "뜻 숨기기";
    });
  });
  const nextBtn = root.querySelector("#nextBtn");
  nextBtn.addEventListener("click", actions.nextQuestion);
  nextBtn.focus({ preventScroll: true });
}

function renderQuizScreen(root, ctx) {
  if (ctx.question.selectedAnswer === null) {
    renderQuestionPhase(root, ctx);
  } else {
    renderDetailPhase(root, ctx);
  }
}

;

/* ── js/screens/typingQuiz.js ── */
const TYPING_REVEAL_DELAY_MS = 600;

const WORD_MODES = {
  choice: { emoji: "📚", title: "뜻 보고 고르기", desc: "뜻을 보고 알맞은 단어 고르기" },
  spelling: { emoji: "⌨️", title: "철자 쓰기", desc: "뜻을 보고 영어 단어를 직접 쓰기" },
  dictation: { emoji: "🎧", title: "받아쓰기", desc: "발음을 듣고 영어 단어를 쓰기" },
};

// ctx: { mode, question, index, total, score, level, actions: { submit, next, quit } }
function renderTypingQuizScreen(root, ctx) {
  if (ctx.question.selectedAnswer === null) renderTypingQuestionPhase(root, ctx);
  else renderTypingDetailPhase(root, ctx);
}

function typingTopbar(ctx, progressCount) {
  return quizTopbarHtml({
    label: WORD_MODES[ctx.mode].title,
    index: ctx.index,
    total: ctx.total,
    scoreText: `점수 ${ctx.score}점`,
    progressCount,
  });
}

function typingHintHtml(type, data) {
  if (type === "picture") return `<div class="hint-item hint-picture">${data.emoji}</div>`;
  if (type === "desc") return `<div class="hint-item hint-desc">${data.desc}</div>`;
  if (type === "meaning") return `<div class="hint-item hint-desc">뜻: <b>${data.meaningKo}</b></div>`;
  return `<div class="hint-item hint-letter">${letterHintPattern(data.word)}</div>`;
}

function renderTypingQuestionPhase(root, ctx) {
  const { mode, question, index, level, actions } = ctx;
  const { data } = question;
  const isDictation = mode === "dictation";
  const hints = isDictation
    ? [["meaning", "💬 뜻 보기"], ["letter", "🔤 글자 수"]]
    : [["picture", "🖼 그림"], ["desc", "💬 설명"], ["letter", "🔤 글자 수"]];
  question.hintsUsed ||= {};

  root.innerHTML = `
    <div class="screen screen-quiz"${levelThemeStyle(level)}>
      ${typingTopbar(ctx, index)}
      <div class="question-card">
        ${
          isDictation
            ? `
          <p class="question-label">잘 듣고 영어 단어를 써 보세요</p>
          <div class="listen-row">
            <button class="big-listen-btn" id="playBtn" aria-label="다시 듣기">🔊</button>
            <button class="listen-btn" id="slowBtn">🐢 천천히</button>
          </div>`
            : `
          <p class="question-label">이 뜻을 가진 영어 단어를 써 보세요</p>
          <p class="question-meaning">${data.meaningKo}</p>`
        }
      </div>

      <div class="hint-row" style="grid-template-columns:repeat(${hints.length}, 1fr)">
        ${hints
          .map(([type, label]) => `<button class="hint-btn" data-hint="${type}" ${question.hintsUsed[type] ? "disabled" : ""}>${label}${question.hintsUsed[type] ? " ✓" : ""}</button>`)
          .join("")}
      </div>
      <div class="hint-reveal" id="hintReveal">${hints.filter(([t]) => question.hintsUsed[t]).map(([t]) => typingHintHtml(t, data)).join("")}</div>

      <form class="typing-form" id="typingForm" autocomplete="off">
        <input class="typing-input" id="typingInput" type="text" placeholder="영어로 입력하세요"
          autocapitalize="off" autocorrect="off" spellcheck="false" enterkeyhint="done" aria-label="정답 입력" />
        <div class="typing-actions">
          <button type="button" class="secondary-btn" id="skipBtn">모르겠어요</button>
          <button type="submit" class="primary-btn">확인</button>
        </div>
      </form>
    </div>
  `;

  bindQuitConfirm(root, actions.quit);

  const input = root.querySelector("#typingInput");
  const reveal = root.querySelector("#hintReveal");
  root.querySelectorAll("[data-hint]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const type = btn.dataset.hint;
      if (question.hintsUsed[type]) return;
      question.hintsUsed[type] = true;
      btn.disabled = true;
      btn.textContent += " ✓";
      reveal.insertAdjacentHTML("beforeend", typingHintHtml(type, data));
      input.focus();
    });
  });

  if (isDictation) {
    root.querySelector("#playBtn").addEventListener("click", () => speak(data.word, { rate: 0.85 }));
    root.querySelector("#slowBtn").addEventListener("click", () => speak(data.word, { rate: 0.55 }));
    if (!question.autoPlayed) {
      question.autoPlayed = true;
      speak(data.word, { rate: 0.85 });
    }
  }

  let done = false;
  const finish = (typed) => {
    if (done) return;
    done = true;
    const isCorrect = typed !== "" && normalizeTyped(typed) === normalizeTyped(data.word);
    input.disabled = true;
    input.classList.add(isCorrect ? "correct" : "wrong");
    answerFeedback(isCorrect, input);
    setTimeout(() => actions.submit(typed, isCorrect), TYPING_REVEAL_DELAY_MS);
  };

  root.querySelector("#typingForm").addEventListener("submit", (e) => {
    e.preventDefault();
    if (input.value.trim() === "") {
      input.focus();
      return;
    }
    finish(input.value);
  });
  root.querySelector("#skipBtn").addEventListener("click", () => finish(""));
  input.focus({ preventScroll: true });
}

function renderTypingDetailPhase(root, ctx) {
  const { question, index, total, level, actions } = ctx;
  const { data } = question;
  const isCorrect = question.selectedAnswer === question.correctAnswer;
  const typed = question.typedAnswer || "";
  const nearMiss = !isCorrect && typed !== "" && editDistance(normalizeTyped(typed), normalizeTyped(data.word)) === 1;
  const ex = data.examples[0];

  root.innerHTML = `
    <div class="screen screen-quiz"${levelThemeStyle(level)}>
      ${typingTopbar(ctx, index + 1)}
      <div class="result-banner ${isCorrect ? "correct" : "wrong"}" role="status">
        ${isCorrect ? "🎉 정답이에요!" : nearMiss ? "😮 아깝다! 한 글자만 달라요" : "❌ 아쉬워요!"}
      </div>

      ${
        !isCorrect
          ? `
        <div class="typed-compare">
          <div><span class="typed-label">내가 쓴 답</span><span class="typed-value typed-mine">${typed ? escapeHtml(typed) : "(모르겠어요)"}</span></div>
          <div><span class="typed-label">정답</span><span class="typed-value typed-answer">${data.word}</span></div>
        </div>`
          : ""
      }

      <div class="word-detail-card">
        <div class="word-line">
          <span class="word-text">${data.word}</span>
          <button class="speak-btn" id="speakWordBtn" aria-label="발음 듣기" ${speechSupported ? "" : "disabled"}>🔊</button>
          <span class="ipa-text">${data.ipa}</span>
        </div>
        <div class="meaning-text">${data.meaningKo}</div>
        <div class="example-item">
          <div class="example-en">
            <button class="speak-btn" id="speakExampleBtn" aria-label="예문 듣기" ${speechSupported ? "" : "disabled"}>🔊</button>
            <span>${ex.en}</span>
          </div>
          <div class="example-ko example-ko--always">${ex.ko}</div>
        </div>
      </div>

      <button class="primary-btn" id="nextBtn">${index === total - 1 ? "결과 보기" : "다음 문제"}</button>
    </div>
  `;

  bindQuitConfirm(root, actions.quit);
  root.querySelector("#speakWordBtn").addEventListener("click", () => speak(data.word));
  root.querySelector("#speakExampleBtn").addEventListener("click", () => speak(ex.en));
  const nextBtn = root.querySelector("#nextBtn");
  nextBtn.addEventListener("click", actions.next);
  nextBtn.focus({ preventScroll: true });
}

;

/* ── js/screens/result.js ── */

function gradeMessage(score) {
  if (score >= 90) return { emoji: "🏆", text: "최고예요!" };
  if (score >= 70) return { emoji: "🎉", text: "잘했어요!" };
  if (score >= 50) return { emoji: "👍", text: "잘 하고 있어요!" };
  return { emoji: "💪", text: "다음엔 더 잘할 수 있어요!" };
}

function renderResultScreen(root, ctx) {
  const { score, questions, levelLabel, modeTitle, profileName, isNewBest, isReview, nextLevel, levelColor, actions } = ctx;
  const grade = gradeMessage(score);
  const correctCount = questions.filter((q) => q.selectedAnswer === q.correctAnswer).length;
  const wrongCount = questions.length - correctCount;
  const themeStyle = levelColor ? ` style="--primary:${levelColor}"` : "";
  const canPlayAgain = !isReview || getWrongWords(profileName).length > 0;

  root.innerHTML = `
    <div class="screen screen-result"${themeStyle}>
      <h1 class="title">${grade.emoji} ${grade.text}</h1>
      <p class="subtitle">${profileName}님 · ${modeTitle} · ${isReview ? "오답노트 복습" : levelLabel}</p>

      <div class="score-circle">
        <span class="score-number">${score}</span>
        <span class="score-max">/ 100점</span>
      </div>
      <p class="score-breakdown">정답 ${correctCount} · 오답 ${wrongCount}</p>
      ${isNewBest ? `<div class="new-best-badge">🌟 최고 기록 경신!</div>` : ""}

      ${!isReview && nextLevel && score >= 70 ? `
        <button class="next-level-cta" id="nextLevelBtn">
          🚀 다음 단계 "${nextLevel.label}"에 도전해보세요!
        </button>
      ` : ""}
      ${wrongCount > 0 && !isReview ? `
        <button class="review-cta" id="reviewCtaBtn">📝 틀린 단어 바로 복습하기</button>
      ` : ""}

      <div class="answer-summary">
        ${questions
          .map((q, i) => {
            const correct = q.selectedAnswer === q.correctAnswer;
            return `
            <div class="summary-row ${correct ? "correct" : "wrong"}">
              <span class="summary-index">${i + 1}</span>
              <span class="summary-word">${q.data.word}</span>
              <span class="summary-meaning">${q.data.meaningKo}</span>
              <span class="summary-mark">${correct ? "✅" : "❌"}</span>
            </div>
          `;
          })
          .join("")}
      </div>

      ${isReview && !canPlayAgain ? `<div class="new-best-badge">🎉 오답노트를 모두 비웠어요!</div>` : ""}

      <div class="result-actions">
        ${canPlayAgain ? `<button class="primary-btn" id="playAgainBtn">${isReview ? "🔁 남은 오답 다시 풀기" : "🔁 다시 도전하기"}</button>` : ""}
        <button class="${canPlayAgain ? "secondary-btn" : "primary-btn"}" id="changeLevelBtn">단계 다시 선택</button>
        <button class="secondary-btn" id="goHomeBtn">홈으로</button>
      </div>
    </div>
  `;

  root.querySelector("#playAgainBtn")?.addEventListener("click", actions.playAgain);
  root.querySelector("#changeLevelBtn").addEventListener("click", actions.changeLevel);
  root.querySelector("#goHomeBtn").addEventListener("click", actions.goHome);
  root.querySelector("#nextLevelBtn")?.addEventListener("click", () => actions.selectLevel(nextLevel.id));
  root.querySelector("#reviewCtaBtn")?.addEventListener("click", actions.startReview);

  if (score >= 80) burstConfetti(36);
}

;

/* ── js/screens/grammar.js ── */
function renderGrammarListScreen(root, { profileName, startQuiz, startReview, backToHome }) {
  const wrongCount = getGrammarWrongIds(profileName).length;
  const doneCount = GRAMMAR_TOPICS.filter((t) => getSectionBest(profileName, "grammar", t.id)).length;

  root.innerHTML = `
    <div class="screen screen-grammar-list">
      <button class="back-btn" id="backBtn">← 문법</button>
      <h1 class="title">✏️ 문법 문제</h1>
      <p class="subtitle">주제를 고르면 바로 문제가 나와요. 개념은 📘 문법 노트에서 봐요 · ${doneCount} / ${GRAMMAR_TOPICS.length} 완료</p>

      ${wrongCount > 0 ? `
        <button class="review-card" id="reviewBtn">
          <span class="review-emoji">📝</span>
          <span class="review-text">
            <span class="review-title">문법 오답노트 복습</span>
            <span class="review-desc">틀렸던 문제 ${wrongCount}개를 다시 풀어봐요</span>
          </span>
        </button>
      ` : ""}

      <div class="level-grid">
        ${GRAMMAR_TOPICS.map((topic, i) => {
          const level = levelById(topic.levelId);
          const best = getSectionBest(profileName, "grammar", topic.id);
          const perfect = best && best.correct === best.total;
          return `
            <button class="level-card topic-card" data-id="${topic.id}" style="--accent:${level.color}">
              <span class="level-icon">${topic.emoji}</span>
              <span class="topic-text">
                <span class="level-label">${i + 1}. ${topic.title}</span>
                <span class="topic-summary">${topic.summary}</span>
                <span class="topic-level">${shortLevelLabel(level)}</span>
              </span>
              <span class="level-best${best ? "" : " level-best-empty"}">${perfect ? "⭐ " : ""}${ratioLabel(best)}</span>
            </button>
          `;
        }).join("")}
      </div>
    </div>
  `;

  root.querySelector("#backBtn").addEventListener("click", backToHome);
  root.querySelector("#reviewBtn")?.addEventListener("click", startReview);
  root.querySelectorAll(".topic-card").forEach((btn) => {
    btn.addEventListener("click", () => startQuiz(btn.dataset.id));
  });
}

;

/* ── js/screens/mcQuiz.js ── */
const MC_REVEAL_DELAY_MS = 700;
const LONG_CHOICE_LENGTH = 16;

// ctx: { question, index, total, correctCount, label, level, contextHtml, actions: { select, next, quit } }
function renderMcQuizScreen(root, ctx) {
  if (ctx.question.selectedAnswer === null) renderMcQuestionPhase(root, ctx);
  else renderMcDetailPhase(root, ctx);
}

function mcTopbar(ctx, progressCount) {
  return quizTopbarHtml({
    label: ctx.label,
    index: ctx.index,
    total: ctx.total,
    scoreText: `맞힘 ${ctx.correctCount}`,
    progressCount,
  });
}

function mcContext(ctx, open) {
  if (!ctx.contextHtml) return "";
  return `
    <details class="context-card"${open ? " open" : ""}>
      <summary>📄 지문 ${open ? "" : "다시 "}보기</summary>
      <div class="context-body">${ctx.contextHtml}</div>
    </details>
  `;
}

function renderMcQuestionPhase(root, ctx) {
  const { question, index, level, actions } = ctx;
  const isLong = !question.bigChoices && question.choices.some((c) => c.length > LONG_CHOICE_LENGTH);

  root.innerHTML = `
    <div class="screen screen-quiz"${levelThemeStyle(level)}>
      ${mcTopbar(ctx, index)}
      ${mcContext(ctx, true)}
      <div class="question-card">
        <p class="question-label">${question.label}</p>
        <p class="${question.bigEmoji ? "question-emoji" : question.big ? "question-meaning" : "grammar-question"}">${withBlank(question.q)}</p>
        ${question.ko ? `<p class="grammar-question-ko">${question.ko}</p>` : ""}
        ${
          question.speakText
            ? `<div class="listen-row">
          <button class="listen-btn" id="wordSayBtn" ${speechSupported ? "" : "disabled"}>🔊 다시 듣기</button>
          <button class="listen-btn" id="wordSlowBtn" ${speechSupported ? "" : "disabled"}>🐢 천천히</button>
        </div>`
            : ""
        }
        ${
          question.dialog
            ? `<div class="listen-row">
          <button class="listen-btn" id="dialogBtn" ${speechSupported ? "" : "disabled"}>▶ 대화 듣기</button>
          <button class="listen-btn" id="dialogSlowBtn" ${speechSupported ? "" : "disabled"}>🐢 천천히</button>
        </div>`
            : ""
        }
      </div>
      <div class="choice-grid${question.bigChoices ? " choice-grid--emoji" : isLong ? " choice-grid--list" : ""}">
        ${question.choices
          .map((c, i) => `<button class="choice-btn${isLong ? " choice-btn--long" : ""}" data-index="${i}">${c}</button>`)
          .join("")}
      </div>
    </div>
  `;

  bindQuitConfirm(root, () => {
    stopSpeaking();
    actions.quit();
  });
  if (question.speakText) {
    root.querySelector("#wordSayBtn").addEventListener("click", () => speak(question.speakText, { rate: 0.85 }));
    root.querySelector("#wordSlowBtn").addEventListener("click", () => speak(question.speakText, { rate: 0.55 }));
    // 문제를 열면 한 번 자동으로 들려준다
    if (!question.autoPlayed) {
      question.autoPlayed = true;
      setTimeout(() => speak(question.speakText, { rate: 0.85 }), 300);
    }
  }
  if (question.dialog) {
    root.querySelector("#dialogBtn").addEventListener("click", () => playDialog(question.dialog));
    root.querySelector("#dialogSlowBtn").addEventListener("click", () => playDialog(question.dialog, { rate: 0.65 }));
    // 문제를 열면 한 번 자동으로 들려준다
    if (!question.autoPlayed) {
      question.autoPlayed = true;
      setTimeout(() => playDialog(question.dialog), 400);
    }
  }

  let answered = false;
  root.querySelectorAll(".choice-btn").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (answered) return;
      answered = true;
      const choice = question.choices[Number(btn.dataset.index)];

      root.querySelectorAll(".choice-btn").forEach((b) => {
        b.disabled = true;
        const c = question.choices[Number(b.dataset.index)];
        if (c === question.correctAnswer) b.classList.add("correct");
        else if (b === btn) b.classList.add("wrong");
      });

      answerFeedback(choice === question.correctAnswer, btn);

      setTimeout(() => actions.select(choice), MC_REVEAL_DELAY_MS);
    });
  });
}

function renderMcDetailPhase(root, ctx) {
  const { question, index, total, level, actions } = ctx;
  const isCorrect = question.selectedAnswer === question.correctAnswer;
  const isLast = index === total - 1;

  root.innerHTML = `
    <div class="screen screen-quiz"${levelThemeStyle(level)}>
      ${mcTopbar(ctx, index + 1)}
      <div class="result-banner ${isCorrect ? "correct" : "wrong"}" role="status">
        ${isCorrect ? "🎉 정답이에요!" : `❌ 아쉬워요! 정답은 "${question.correctAnswer}"`}
      </div>

      <div class="explain-card">
        <p class="${question.bigEmoji ? "question-emoji" : "grammar-question"}">${question.speakText && question.speakText !== question.correctAnswer ? `${question.correctAnswer} <b>${question.speakText}</b>` : question.speakText ? `<b>${question.correctAnswer}</b>` : question.big ? question.q : withBlank(question.q, question.correctAnswer)}</p>
        ${question.ko ? `<p class="grammar-question-ko">${question.ko}</p>` : ""}
        ${!isCorrect ? `<p class="explain-mine">내가 고른 답: <b>${question.selectedAnswer}</b></p>` : ""}
        <div class="explain-body">
          <span class="explain-icon">💡</span>
          <p>${question.explain}</p>
        </div>
        ${question.dialog ? `<button class="listen-btn" id="dialogBtn" ${speechSupported ? "" : "disabled"}>🔊 대화 다시 듣기</button>` : ""}
        ${question.listenText ? `<button class="listen-btn" id="listenBtn" ${speechSupported ? "" : "disabled"}>🔊 ${question.kind === "word" ? "발음 듣기" : "문장 듣기"}</button>` : ""}
      </div>
      ${mcContext(ctx, false)}

      <button class="primary-btn" id="nextBtn">${isLast ? "결과 보기" : "다음 문제"}</button>
    </div>
  `;

  bindQuitConfirm(root, actions.quit);
  root.querySelector("#listenBtn")?.addEventListener("click", () => speak(question.listenText));
  root.querySelector("#dialogBtn")?.addEventListener("click", () => playDialog(question.dialog));
  const nextBtn = root.querySelector("#nextBtn");
  nextBtn.addEventListener("click", actions.next);
  nextBtn.focus({ preventScroll: true });
}

;

/* ── js/screens/scoreResult.js ── */
// 문법 · 독해 · 끊어 읽기 · 오늘의 학습이 함께 쓰는 결과 화면.
// ctx: { subtitle, correct, total, level, isNewBest, rows: [{ html, ok }], reviewCta: { label, onClick }?,
//        actions: [{ label, onClick, primary? }] }
function renderScoreResultScreen(root, ctx) {
  const { subtitle, correct, total, level, isNewBest, rows, reviewCta, actions } = ctx;
  const percent = Math.round((correct / total) * 100);
  const grade = gradeMessage(percent);

  root.innerHTML = `
    <div class="screen screen-result"${levelThemeStyle(level)}>
      <h1 class="title">${grade.emoji} ${grade.text}</h1>
      <p class="subtitle">${subtitle}</p>

      <div class="score-circle">
        <span class="score-number">${correct}</span>
        <span class="score-max">/ ${total}문제</span>
      </div>
      <p class="score-breakdown">정답률 ${percent}%</p>
      ${isNewBest ? `<div class="new-best-badge">🌟 최고 기록 경신!</div>` : ""}
      ${reviewCta ? `<button class="review-cta" id="reviewCtaBtn">${reviewCta.label}</button>` : ""}

      <div class="answer-summary">
        ${rows
          .map(
            (row, i) => `
          <div class="summary-row">
            <span class="summary-index">${i + 1}</span>
            <span class="summary-meaning summary-meaning--text">${row.html}</span>
            <span class="summary-mark">${row.ok ? "✅" : "❌"}</span>
          </div>
        `
          )
          .join("")}
      </div>

      ${(() => {
        // 주요 버튼 하나만 크게, 나머지는 작은 링크 줄로
        const mainIndex = Math.max(0, actions.findIndex((a) => a.primary));
        const rest = actions.map((a, i) => ({ a, i })).filter(({ i }) => i !== mainIndex);
        return `
      <div class="result-actions">
        <button class="primary-btn" data-action="${mainIndex}">${actions[mainIndex].label}</button>
        ${rest.length ? `<div class="result-links">${rest.map(({ a, i }) => `<button class="link-btn" data-action="${i}">${a.label}</button>`).join("")}</div>` : ""}
      </div>`;
      })()}
    </div>
  `;

  root.querySelector("#reviewCtaBtn")?.addEventListener("click", reviewCta.onClick);
  root.querySelectorAll("[data-action]").forEach((btn) => {
    btn.addEventListener("click", actions[Number(btn.dataset.action)].onClick);
  });

  if (percent >= 80) burstConfetti(36);
}

;

/* ── js/screens/reading.js ── */
const SHADOW_PAUSE_PER_WORD_MS = 650;
const SHADOW_MIN_PAUSE_MS = 1800;
const READING_RATES = { normal: 0.9, slow: 0.65 };

function findPassage(id) {
  return READING_PASSAGES.find((p) => p.id === id) || null;
}

// 문장 안에서 단어장 단어의 첫 등장 위치를 찾아 버튼으로 감싼다. 원문 기준으로 잘라 붙여 HTML이 깨지지 않게 한다.
function glossedSentence(en, glossary) {
  const ranges = [];
  glossary.forEach((g, gi) => {
    const m = new RegExp(`\\b${escapeRegExp(g.w)}\\b`, "i").exec(en);
    if (m && !ranges.some((r) => m.index < r.end && m.index + m[0].length > r.start)) {
      ranges.push({ start: m.index, end: m.index + m[0].length, gi });
    }
  });
  ranges.sort((a, b) => a.start - b.start);

  let html = "";
  let pos = 0;
  for (const r of ranges) {
    html += en.slice(pos, r.start) + `<button class="gloss" data-gloss="${r.gi}">${en.slice(r.start, r.end)}</button>`;
    pos = r.end;
  }
  return html + en.slice(pos);
}

// mode: read(읽기 연습) | quiz(독해 문제)
// 📖 읽기: 같은 지문 목록에서 '읽기 연습'과 '독해 문제'를 바꿔 가며 쓴다.
function renderReadingListScreen(root, { profileName, mode, openPassage, startQuiz, backToHome, setMode }) {
  const isRead = mode === "read";
  const doneCount = READING_PASSAGES.filter((p) =>
    isRead ? isPassageRead(profileName, p.id) : getSectionBest(profileName, "reading", p.id)
  ).length;

  root.innerHTML = `
    <div class="screen screen-reading-list">
      <button class="back-btn" id="backBtn">← 홈</button>
      <h1 class="title">📖 읽기</h1>
      <div class="segmented segmented--wide" role="tablist" aria-label="읽기 방식">
        <button class="segmented-btn${isRead ? " active" : ""}" data-rmode="read" role="tab" aria-selected="${isRead}">🔊 읽기 연습</button>
        <button class="segmented-btn${isRead ? "" : " active"}" data-rmode="quiz" role="tab" aria-selected="${!isRead}">📰 독해 문제</button>
      </div>
      <p class="subtitle">${isRead ? "듣고 따라 읽으며 지문에 익숙해져요" : "글을 읽고 내용을 확인하는 문제를 풀어요"} · ${doneCount} / ${READING_PASSAGES.length} ${isRead ? "읽음" : "완료"}</p>

      ${(() => {
        const levelSection = (level) => {
        const passages = READING_PASSAGES.filter((p) => p.levelId === level.id);
        if (passages.length === 0) return "";
        return `
          <section class="group">
            <h2 class="group-title">${level.emoji} ${shortLevelLabel(level)}</h2>
            <div class="level-grid">
              ${passages
                .map((p) => {
                  const best = getSectionBest(profileName, "reading", p.id);
                  const read = isPassageRead(profileName, p.id);
                  const badge = isRead
                    ? `<span class="level-best${read ? "" : " level-best-empty"}">${read ? "✓ 읽음" : "새 글"}</span>`
                    : `<span class="level-best${best ? "" : " level-best-empty"}">${ratioLabel(best)}</span>`;
                  return `
                  <button class="level-card passage-card" data-id="${p.id}" style="--accent:${level.color}">
                    <span class="level-icon">${p.emoji}</span>
                    <span class="topic-text">
                      <span class="level-label">${p.title}</span>
                      <span class="topic-summary">${p.sentences.length}문장${isRead ? "" : ` · 문제 ${p.questions.length}개`}</span>
                    </span>
                    ${badge}
                  </button>`;
                })
                .join("")}
            </div>
          </section>
        `;
        };
        // 내 단계를 먼저 펼치고, 다른 단계는 접어 둔다
        const { mine, others } = splitByMyLevel(LEVELS, (lv) => [lv.id], myLevelOf(profileName));
        return `${mine.map(levelSection).join("")}${
          others.length ? `<details class="other-levels"><summary class="basic-grade-title">다른 단계 보기 <span class="basic-grade-count">${others.length}단계</span></summary>${others.map(levelSection).join("")}</details>` : ""
        }`;
      })()}
    </div>
  `;

  root.querySelector("#backBtn").addEventListener("click", backToHome);
  root.querySelectorAll("[data-rmode]").forEach((b) => b.addEventListener("click", () => setMode?.(b.dataset.rmode)));
  root.querySelectorAll(".passage-card").forEach((btn) => {
    btn.addEventListener("click", () => (isRead ? openPassage(btn.dataset.id) : startQuiz(btn.dataset.id)));
  });
}

function renderPassageScreen(root, { profileName, passage, startQuiz, backToList, goHome }) {
  const level = levelById(passage.levelId);
  const read = isPassageRead(profileName, passage.id);
  let slow = getSettings().readingSlow === true;
  // 🎙️ 소리 내어 읽기: 음성 인식이 되는 기기에서 문장마다 읽고 맞게 읽은 단어를 표시한다
  const aloud = typeof SpeechRecognitionApi !== "undefined" && !!SpeechRecognitionApi;
  const aloudPassed = new Set();
  const bottomLinks = [
    { label: "📖 지문 목록", onClick: () => { stopPlayback(); backToList(); } },
    { label: "🏠 홈으로", onClick: () => { stopPlayback(); goHome(); } },
  ];

  root.innerHTML = `
    <div class="screen screen-passage"${levelThemeStyle(level)}>
      <button class="back-btn" id="backBtn">← 목록</button>
      <div class="lesson-head">
        <span class="lesson-emoji">${passage.emoji}</span>
        <h1 class="title">${passage.title}</h1>
        <p class="subtitle"><span class="topic-level">${shortLevelLabel(level)}</span>${read ? " · ✓ 읽음" : ""}</p>
      </div>

      <section class="settings-card reading-controls">
        <div class="reading-toolbar">
          <button class="listen-btn" id="listenAllBtn" ${speechSupported ? "" : "disabled"}>▶ 전체 듣기</button>
          <button class="listen-btn" id="shadowBtn" ${speechSupported ? "" : "disabled"}>🗣 따라 읽기</button>
          <button class="listen-btn" id="speedBtn" aria-pressed="${slow}" ${speechSupported ? "" : "disabled"}>${slow ? "🐢 느리게" : "🐇 보통 속도"}</button>
          <button class="listen-btn" id="toggleAllBtn">해석 모두 보기</button>
        </div>
        <p class="settings-help" id="playStatus">밑줄 단어를 누르면 뜻, 문장을 누르면 해석이 나와요. <b>따라 읽기</b>는 한 문장을 들려준 뒤 따라 말할 시간을 줘요.${recSupported ? " <b>⏺</b>를 누르면 내 목소리를 녹음해서 들어 볼 수 있어요." : ""}</p>
        ${aloud ? `<p class="settings-help" id="aloudStatus">🎙️ 문장 옆 마이크를 누르고 <b>소리 내어 읽어</b> 봐요. 80%를 넘으면 통과! · 통과 0 / ${passage.sentences.length}</p>` : ""}
      </section>

      <article class="passage-card-body">
        ${passage.sentences
          .map(
            (s, i) => `
          <div class="passage-sentence" data-sentence="${i}">
            <div class="sentence-btns">
              <button class="speak-btn sentence-speak" data-speak-sentence="${i}" aria-label="${i + 1}번째 문장 듣기" ${speechSupported ? "" : "disabled"}>🔊</button>
              ${aloud ? `<button class="speak-btn sentence-mic" data-mic="${i}" aria-label="${i + 1}번째 문장 소리 내어 읽기">🎙️</button>` : ""}
              ${recorderHtml("s:" + s.en, true)}
            </div>
            <div class="passage-text" tabindex="0" role="button" aria-expanded="false">
              <p class="passage-en">${glossedSentence(s.en, passage.glossary)}</p>
              <p class="passage-ko" hidden>${s.ko}</p>
              <p class="shadow-cue" hidden>🗣 따라 말해 보세요</p>
              <div class="aloud-result" hidden></div>
            </div>
          </div>
        `
          )
          .join("")}
      </article>

      <div class="gloss-bar" id="glossBar" hidden aria-live="polite"></div>

      <div class="sticky-cta passage-actions">
        ${read ? "" : `<button class="secondary-btn" id="markReadBtn">✓ 다 읽었어요</button>`}
        <button class="primary-btn" id="startQuizBtn">✏️ 문제 풀기 (${passage.questions.length})</button>
      </div>

      ${bottomNavHtml(bottomLinks)}
    </div>
  `;

  const sentenceEls = [...root.querySelectorAll(".passage-sentence")];
  const status = root.querySelector("#playStatus");
  const setOpen = (el, open) => {
    el.querySelector(".passage-ko").hidden = !open;
    el.querySelector(".passage-text").setAttribute("aria-expanded", String(open));
    el.classList.toggle("open", open);
  };

  sentenceEls.forEach((el) => {
    const text = el.querySelector(".passage-text");
    const toggle = () => setOpen(el, el.querySelector(".passage-ko").hidden);
    text.addEventListener("click", (e) => {
      if (!e.target.closest(".gloss")) toggle();
    });
    text.addEventListener("keydown", (e) => {
      if ((e.key === "Enter" || e.key === " ") && !e.target.closest(".gloss")) {
        e.preventDefault();
        toggle();
      }
    });
  });

  const toggleAllBtn = root.querySelector("#toggleAllBtn");
  toggleAllBtn.addEventListener("click", () => {
    const openAll = sentenceEls.some((el) => el.querySelector(".passage-ko").hidden);
    sentenceEls.forEach((el) => setOpen(el, openAll));
    toggleAllBtn.textContent = openAll ? "해석 모두 숨기기" : "해석 모두 보기";
  });

  // ── 이어 듣기 · 따라 읽기 ──
  let playToken = 0;
  let pauseTimer = null;
  const listenAllBtn = root.querySelector("#listenAllBtn");
  const shadowBtn = root.querySelector("#shadowBtn");

  const clearPlaying = () => {
    sentenceEls.forEach((el) => {
      el.classList.remove("playing");
      el.querySelector(".shadow-cue").hidden = true;
    });
  };
  const stopPlayback = (message) => {
    playToken += 1;
    if (aloud) stopRecognition();
    stopRecording();
    clearTimeout(pauseTimer);
    stopSpeaking();
    clearPlaying();
    listenAllBtn.textContent = "▶ 전체 듣기";
    shadowBtn.textContent = "🗣 따라 읽기";
    if (message) status.textContent = message;
  };
  const markRead = () => {
    markPassageRead(profileName, passage.id);
    root.querySelector("#markReadBtn")?.remove();
    announceBadges(checkNewBadges(profileName));
  };

  const play = (index, shadow, token) => {
    if (token !== playToken || !root.contains(sentenceEls[0])) return;
    if (index >= sentenceEls.length) {
      stopPlayback(shadow ? "🎉 끝까지 따라 읽었어요! 한 번 더 하면 더 자연스러워져요." : "끝까지 들었어요.");
      markRead();
      return;
    }
    clearPlaying();
    const el = sentenceEls[index];
    el.classList.add("playing");
    el.scrollIntoView({ block: "center", behavior: "smooth" });
    status.textContent = `${index + 1} / ${sentenceEls.length} 문장 ${shadow ? "듣는 중…" : "재생 중"}`;
    const sentence = passage.sentences[index].en;
    speak(sentence, {
      rate: slow ? READING_RATES.slow : READING_RATES.normal,
      onEnd: () => {
        if (token !== playToken) return;
        if (!shadow) {
          pauseTimer = setTimeout(() => play(index + 1, shadow, token), 350);
          return;
        }
        el.querySelector(".shadow-cue").hidden = false;
        status.textContent = `${index + 1} / ${sentenceEls.length} 문장 · 따라 말해 보세요`;
        const pause = Math.max(SHADOW_MIN_PAUSE_MS, sentence.split(" ").length * SHADOW_PAUSE_PER_WORD_MS * (slow ? 1.3 : 1));
        pauseTimer = setTimeout(() => play(index + 1, shadow, token), pause);
      },
    });
  };

  const startPlayback = (shadow) => {
    const wasPlaying = (shadow ? shadowBtn : listenAllBtn).textContent.startsWith("⏹");
    stopPlayback();
    if (wasPlaying) {
      status.textContent = "멈췄어요.";
      return;
    }
    (shadow ? shadowBtn : listenAllBtn).textContent = "⏹ 멈추기";
    play(0, shadow, playToken);
  };
  bindRecorders(root);
  listenAllBtn.addEventListener("click", () => startPlayback(false));
  shadowBtn.addEventListener("click", () => startPlayback(true));

  root.querySelectorAll("[data-mic]").forEach((btn) =>
    btn.addEventListener("click", (e) => {
      e.stopPropagation();
      const wasListening = btn.classList.contains("listening");
      stopPlayback();
      root.querySelectorAll(".sentence-mic.listening").forEach((b) => b.classList.remove("listening"));
      if (wasListening) return;
      const i = Number(btn.dataset.mic);
      const target = passage.sentences[i].en;
      const out = sentenceEls[i].querySelector(".aloud-result");
      const rec = new SpeechRecognitionApi();
      rec.lang = "en-US";
      rec.interimResults = false;
      rec.maxAlternatives = 3;
      activeRecognition = rec;
      btn.classList.add("listening");
      out.hidden = false;
      out.innerHTML = `<p class="speak-heard">👂 듣고 있어요… 문장을 소리 내어 읽어요</p>`;
      rec.onresult = (ev) => {
        const alts = [...ev.results[0]].map((r) => r.transcript);
        const heard = alts.sort((x, y) => speakingMatch(target, y).score - speakingMatch(target, x).score)[0];
        const m = speakingMatch(target, heard);
        const ok = m.score >= SPEAKING_PASS;
        out.innerHTML = `<p class="speak-words">${m.words.map((w, k) => `<span class="${m.hit[k] ? "hit" : "miss"}">${w}</span>`).join(" ")}</p>
          <p class="speak-score ${ok ? "ok" : ""}">${ok ? "🎉" : "💪"} ${Math.round(m.score * 100)}%${ok ? " · 통과!" : " · 빨간 단어를 또박또박 다시 읽어 봐요"}</p>`;
        if (ok && !aloudPassed.has(i)) {
          aloudPassed.add(i);
          playSound("correct");
          recordActivity(profileName);
          recordBestCount(profileName, "aloud", passage.id, aloudPassed.size, passage.sentences.length);
          root.querySelector("#aloudStatus").innerHTML = `🎙️ 소리 내어 읽기 · 통과 <b>${aloudPassed.size}</b> / ${passage.sentences.length}`;
          if (aloudPassed.size === passage.sentences.length) {
            burstConfetti(40);
            showToast(`<span class="toast-emoji">🎙️</span><span>모든 문장을 소리 내어 읽었어요!</span>`);
            announceBadges(checkNewBadges(profileName));
          }
        }
      };
      rec.onerror = (ev) => {
        out.innerHTML = ["not-allowed", "service-not-allowed", "audio-capture"].includes(ev.error) ? micHelpHtml().replace(/<br>.*<\/p>$/, "</p>") : recognitionErrorHtml(ev.error).replace("말해", "읽어");
      };
      rec.onend = () => {
        if (activeRecognition === rec) activeRecognition = null;
        btn.classList.remove("listening");
      };
      try {
        rec.start();
      } catch {
        activeRecognition = null;
        btn.classList.remove("listening");
      }
    })
  );

  root.querySelectorAll("[data-speak-sentence]").forEach((btn) =>
    btn.addEventListener("click", () => {
      stopPlayback();
      speak(passage.sentences[Number(btn.dataset.speakSentence)].en, { rate: slow ? READING_RATES.slow : READING_RATES.normal });
    })
  );

  const speedBtn = root.querySelector("#speedBtn");
  speedBtn.addEventListener("click", () => {
    slow = !slow;
    updateSettings({ readingSlow: slow });
    speedBtn.textContent = slow ? "🐢 느리게" : "🐇 보통 속도";
    speedBtn.setAttribute("aria-pressed", String(slow));
  });

  // ── 단어 뜻 · 단어장 추가 ──
  const glossBar = root.querySelector("#glossBar");
  root.querySelectorAll(".gloss").forEach((btn) => {
    btn.addEventListener("click", () => {
      const gi = Number(btn.dataset.gloss);
      const g = passage.glossary[gi];
      const saved = isGlossInVocab(profileName, passage, gi);
      root.querySelectorAll(".gloss.active").forEach((b) => b.classList.remove("active"));
      btn.classList.add("active");
      glossBar.hidden = false;
      glossBar.innerHTML = `
        <span class="gloss-word">${g.w}</span>
        <span class="gloss-meaning">${g.ko}</span>
        <button class="speak-btn" id="glossSpeakBtn" aria-label="발음 듣기" ${speechSupported ? "" : "disabled"}>🔊</button>
        <button class="gloss-add" id="glossAddBtn" ${saved ? "disabled" : ""}>${saved ? "✓ 단어장" : "＋ 단어장"}</button>
        <button class="gloss-close" id="glossCloseBtn" aria-label="닫기">✕</button>
      `;
      glossBar.querySelector("#glossSpeakBtn").addEventListener("click", () => speak(g.w));
      glossBar.querySelector("#glossAddBtn").addEventListener("click", (e) => {
        addGlossToVocab(profileName, passage, gi);
        e.currentTarget.disabled = true;
        e.currentTarget.textContent = "✓ 단어장";
        showToast(`<span class="toast-emoji">📇</span><span>단어장에 추가: <b>${g.w}</b></span>`);
      });
      glossBar.querySelector("#glossCloseBtn").addEventListener("click", () => {
        glossBar.hidden = true;
        btn.classList.remove("active");
      });
    });
  });

  root.querySelector("#markReadBtn")?.addEventListener("click", () => {
    markRead();
    showToast(`<span class="toast-emoji">✓</span><span>읽음으로 표시했어요: ${passage.title}</span>`);
  });
  root.querySelector("#backBtn").addEventListener("click", () => {
    stopPlayback();
    backToList();
  });
  root.querySelector("#startQuizBtn").addEventListener("click", () => {
    stopPlayback();
    startQuiz();
  });
  bindBottomNav(root, bottomLinks);
}

function passageContextHtml(passage) {
  return passage.sentences.map((s) => `<p>${s.en}</p>`).join("");
}

;

/* ── js/screens/chunks.js ── */
const CHUNK_STEPS = [
  { role: "S", prompt: "주어를 찾아 누르세요", tip: "'~은/는/이/가'로 해석되는 덩어리예요" },
  { role: "V", prompt: "동사를 찾아 누르세요", tip: "주어가 '어찌하다/어떠하다'에 해당하는 말이에요" },
];

function findChunkSet(id) {
  return CHUNK_SETS.find((s) => s.id === id) || null;
}

function buildChunkSession(setId) {
  return findChunkSet(setId).sentences.map((sentence) => ({ sentence, step: 0, mistakes: 0, wrongChunk: null }));
}

function roleLegendHtml() {
  return `
    <div class="role-legend">
      ${Object.values(CHUNK_ROLES).map((r) => `<span class="role-chip" style="--role:${r.color}">${r.label}</span>`).join("")}
    </div>
  `;
}

function renderChunkIntroScreen(root, { profileName, startSet, backToHome }) {
  root.innerHTML = `
    <div class="screen screen-chunks-intro">
      <button class="back-btn" id="backBtn">← 홈</button>
      <h1 class="title">✂️ 끊어 읽기</h1>
      <p class="subtitle">긴 문장도 덩어리로 나누면 앞에서부터 바로 읽혀요</p>

      <section class="lesson-section">
        <h2 class="section-title">이렇게 연습해요</h2>
        <div class="lesson-point"><span class="lesson-point-num">1</span><p class="lesson-point-text">문장에서 <b>주어</b> 덩어리를 찾아 눌러요.</p></div>
        <div class="lesson-point"><span class="lesson-point-num">2</span><p class="lesson-point-text">이어서 <b>동사</b>를 찾아 눌러요. 주어를 꾸미는 말(수식어)에 속지 마세요!</p></div>
        <div class="lesson-point"><span class="lesson-point-num">3</span><p class="lesson-point-text">덩어리별 해석(직독직해)을 보며 앞에서부터 읽는 연습을 해요.</p></div>
        ${roleLegendHtml()}
      </section>

      <div class="level-grid">
        ${CHUNK_SETS.map((set) => {
          const level = levelById(set.levelId);
          const best = getSectionBest(profileName, "chunks", set.id);
          return `
            <button class="level-card chunk-set-card" data-id="${set.id}" style="--accent:${level.color}">
              <span class="level-icon">${set.emoji}</span>
              <span class="topic-text">
                <span class="level-label">${set.title}</span>
                <span class="topic-summary">${set.desc}</span>
                <span class="topic-level">${shortLevelLabel(level)} · ${set.sentences.length}문장</span>
              </span>
              <span class="level-best${best ? "" : " level-best-empty"}">${ratioLabel(best)}</span>
            </button>
          `;
        }).join("")}
      </div>
    </div>
  `;

  root.querySelector("#backBtn").addEventListener("click", backToHome);
  root.querySelectorAll(".chunk-set-card").forEach((btn) => {
    btn.addEventListener("click", () => startSet(btn.dataset.id));
  });
}

// ctx: { set, item, index, total, correctCount, actions: { tapChunk, next, quit } }
function renderChunkSessionScreen(root, ctx) {
  const { set, item, index, total, correctCount, actions } = ctx;
  const level = levelById(set.levelId);
  const { sentence, step } = item;
  const done = step >= CHUNK_STEPS.length;
  const current = CHUNK_STEPS[step];

  const chunkHtml = sentence.chunks
    .map((c, i) => {
      const found = !done && CHUNK_STEPS.slice(0, step).some((s) => s.role === c.role);
      const role = CHUNK_ROLES[c.role];
      const cls = done || found ? " revealed" : item.wrongChunk === i ? " wrong shake" : "";
      return `
        <button class="chunk${cls}" data-chunk="${i}" style="--role:${role.color}" ${done || found ? "disabled" : ""}>
          <span class="chunk-en">${c.en}</span>
          ${done || found ? `<span class="chunk-role">${role.label}</span>` : ""}
        </button>`;
    })
    .join(`<span class="chunk-slash" aria-hidden="true">/</span>`);

  root.innerHTML = `
    <div class="screen screen-quiz"${levelThemeStyle(level)}>
      ${quizTopbarHtml({ label: `✂️ 끊어 읽기 · ${set.title}`, index, total, scoreText: `한 번에 ${correctCount}`, progressCount: done ? index + 1 : index })}

      <div class="question-card chunk-card">
        <p class="question-label">${done ? (item.mistakes === 0 ? "🎉 한 번에 찾았어요!" : "👍 덩어리로 나눠 읽어 봐요") : current.prompt}</p>
        <div class="chunk-row">${chunkHtml}</div>
        ${!done ? `<p class="chunk-tip">💡 ${current.tip}</p>` : ""}
      </div>

      ${
        done
          ? `
        <div class="explain-card">
          <p class="section-title">직독직해</p>
          <p class="chunk-translation">${sentence.chunks.map((c) => `<span style="--role:${CHUNK_ROLES[c.role].color}">${c.ko}</span>`).join(" / ")}</p>
          <div class="explain-body"><span class="explain-icon">📝</span><p>${sentence.ko}</p></div>
          <button class="listen-btn" id="listenBtn" ${speechSupported ? "" : "disabled"}>🔊 문장 듣기</button>
        </div>
        ${roleLegendHtml()}
        <button class="primary-btn" id="nextBtn">${index === total - 1 ? "결과 보기" : "다음 문장"}</button>`
          : ""
      }
    </div>
  `;

  bindQuitConfirm(root, actions.quit);
  root.querySelectorAll(".chunk:not([disabled])").forEach((btn) => {
    btn.addEventListener("click", () => actions.tapChunk(Number(btn.dataset.chunk)));
  });
  if (done) {
    root.querySelector("#listenBtn").addEventListener("click", () => speak(sentence.chunks.map((c) => c.en).join(" ")));
    const nextBtn = root.querySelector("#nextBtn");
    nextBtn.addEventListener("click", actions.next);
    nextBtn.focus({ preventScroll: true });
  }
}

;

/* ── js/screens/irregular.js ── */
// 불규칙 동사: 변화표로 공부하고(듣기 · 가리고 외우기) 4지선다로 테스트한다.
const IRREGULAR_QUIZ_SIZE = 10;

const IRREGULAR_NOTES = {
  be: "주어가 I · he · she · it이면 was, you · we · they면 were예요.",
  read: "철자는 그대로지만 과거형 · 과거분사 read는 [레드]로 소리 나요.",
  get: "영국 영어에서는 과거분사로 got도 써요.",
  lie: "'거짓말하다'의 lie는 lied - lied로 규칙 변화해요. lay(놓다)와도 헷갈리지 마세요.",
  lay: "lie(눕다)의 과거형도 lay예요. 목적어가 있으면 '놓다'의 lay예요.",
  find: "found는 '설립하다'라는 다른 동사이기도 해요 (found - founded - founded).",
  rise: "rise는 스스로 오르는 것(목적어 없음), raise(올리다)는 규칙 변화예요.",
  leave: "left는 '왼쪽'이라는 뜻도 있어요.",
  win: "won은 [원]으로 소리 나요. 한국 돈 '원'과 같은 소리예요.",
};

function findIrregularSet(id) {
  return IRREGULAR_SETS.find((s) => s.id === id) || null;
}

function regularized(base) {
  if (base.endsWith("e")) return `${base}d`;
  if (/[^aeiou]y$/.test(base)) return `${base.slice(0, -1)}ied`;
  return `${base}ed`;
}

function irregularFormsText(v) {
  return `${v.base} - ${v.past} - ${v.pp}`;
}

function irregularExplain(v) {
  const pattern = IRREGULAR_PATTERNS.find((p) => p.id === irregularPattern(v));
  const note = IRREGULAR_NOTES[v.base];
  return `<b>${irregularFormsText(v)}</b> (${v.ko})<br>${pattern.label}: ${pattern.desc}.${note ? `<br>${note}` : ""}`;
}

// 보기: 같은 동사의 다른 모양 → -ed를 붙인 틀린 모양 → 같은 세트의 다른 동사 순서로 채운다.
function irregularChoices(correct, candidates, fallback, alt) {
  const picked = [];
  const bad = new Set([correct, ...alt]);
  for (const c of [...candidates, ...shuffle(fallback)]) {
    if (picked.length >= 3) break;
    if (!c || bad.has(c) || picked.includes(c)) continue;
    picked.push(c);
  }
  return shuffle([correct, ...picked]);
}

function irregularQuestion(v, set, kind) {
  const others = set.verbs.filter((o) => o !== v);
  const n = (b) => (b.endsWith("e") ? `${b}n` : `${b}en`);
  const forms = {
    past: { q: `${v.base} - ___ - ${v.pp}`, ask: "과거형", correct: v.past, candidates: [v.pp, regularized(v.base), v.base, n(v.base)], fallback: others.map((o) => o.past) },
    pp: { q: `${v.base} - ${v.past} - ___`, ask: "과거분사", correct: v.pp, candidates: [v.past, regularized(v.base), n(v.base), v.base], fallback: others.map((o) => o.pp) },
    base: { q: `___ - ${v.past} - ${v.pp}`, ask: "원형", correct: v.base, candidates: [], fallback: others.map((o) => o.base) },
  }[kind];
  return {
    id: `irr|${set.id}|${v.base}|${kind}`,
    drill: true,
    kind: "irregular",
    label: `빈칸에 알맞은 ${forms.ask}${kind === "pp" ? "를" : "을"} 고르세요`,
    q: forms.q,
    ko: kind === "base" ? null : `${v.base}: ${v.ko}`,
    choices: irregularChoices(forms.correct, forms.candidates, forms.fallback, v.alt),
    correctAnswer: forms.correct,
    explain: irregularExplain(v),
    summary: irregularFormsText(v),
    listenText: `${v.base}, ${v.past.replace(" / ", ", ")}, ${v.pp}`,
    selectedAnswer: null,
  };
}

function buildIrregularQuestions(setId) {
  const set = findIrregularSet(setId);
  if (!set) return [];
  // 과거형 · 과거분사를 주로 묻고, 가끔 원형을 거꾸로 묻는다.
  const kinds = ["past", "pp", "past", "pp", "base"];
  return shuffle(set.verbs)
    .slice(0, IRREGULAR_QUIZ_SIZE)
    .map((v, i) => irregularQuestion(v, set, kinds[i % kinds.length]));
}

// 화면을 떠났다 와도 가리기 · 펼친 단계를 기억한다(앱을 켜 둔 동안).
let irregularHideForms = false;
let irregularOpenSet = null;

function irregularSetToOpen(profileName) {
  if (irregularOpenSet) return irregularOpenSet;
  const level = getPreferredLevel(profileName) || getLastWordLevel(profileName);
  const order = LEVELS.map((lv) => lv.id);
  const mine = order.indexOf(level);
  // 내 단계보다 높지 않은 세트 중 가장 높은 것
  const fit = [...IRREGULAR_SETS].reverse().find((s) => mine >= order.indexOf(s.levelId));
  return (fit || IRREGULAR_SETS[0]).id;
}

function irregularVerbRow(v, setId) {
  const forms = [v.past, v.pp].map((f) => `<span class="irr-form" data-form>${f}</span>`);
  return `
    <li class="irr-row">
      <button class="speak-btn" data-speak="${setId}|${v.base}" aria-label="${v.base} 변화 듣기" ${speechSupported ? "" : "disabled"}>🔊</button>
      <span class="irr-forms"><b class="irr-base">${v.base}</b><span class="irr-arrow">-</span>${forms[0]}<span class="irr-arrow">-</span>${forms[1]}</span>
      <span class="irr-ko">${v.ko}</span>
    </li>`;
}

function renderIrregularScreen(root, { profileName, startTest, back }) {
  const openSet = irregularSetToOpen(profileName);

  root.innerHTML = `
    <div class="screen screen-irregular${irregularHideForms ? " irr-hidden" : ""}">
      <button class="back-btn" id="backBtn">← 홈</button>
      <h1 class="title">🔁 불규칙 동사</h1>
      <p class="subtitle">원형 - 과거형 - 과거분사 외우기</p>

      <section class="lesson-section">
        <h2 class="section-title">이렇게 공부해요</h2>
        <p class="lesson-point-text">대부분의 동사는 <b>-ed</b>를 붙여 과거형을 만들지만 (play - played - played), 자주 쓰는 동사 중에는 모양이 제멋대로 바뀌는 <b>불규칙 동사</b>가 많아요. 과거형은 '어제 한 일', 과거분사(p.p.)는 <b>현재완료(have p.p.)</b>와 <b>수동태(be p.p.)</b>에 써요.</p>
        <div class="irr-patterns">
          ${IRREGULAR_PATTERNS.map((p) => `<div class="irr-pattern-card"><b>${p.label}</b><span>${p.desc}</span><small>${p.example}</small></div>`).join("")}
        </div>
        <p class="settings-help">🔊를 누르면 세 모양을 이어서 읽어 줘요. 소리 내어 따라 말하면 더 잘 외워져요.</p>
        <button class="secondary-btn" id="hideBtn" aria-pressed="${irregularHideForms}">${irregularHideForms ? "👀 모두 보이기" : "🙈 과거형 · 과거분사 가리기"}</button>
        <p class="settings-help" id="hideHelp" ${irregularHideForms ? "" : "hidden"}>가린 칸을 누르면 하나씩 보여요. 먼저 떠올려 보고 확인해요.</p>
      </section>

      ${IRREGULAR_SETS.map((set) => {
        const level = levelById(set.levelId);
        const best = getSectionBest(profileName, "irregular", set.id);
        const groups = IRREGULAR_PATTERNS.map((p) => ({ ...p, verbs: set.verbs.filter((v) => irregularPattern(v) === p.id) })).filter((g) => g.verbs.length);
        return `
        <details class="basic-grade irr-set" data-set="${set.id}" style="--accent:${level.color}" ${set.id === openSet ? "open" : ""}>
          <summary class="basic-grade-title">${set.emoji} ${set.title} <span class="basic-grade-count">${best ? `최고 ${best.correct}/${best.total}` : `${set.verbs.length}개`}</span></summary>
          <div class="irr-body">
            <p class="settings-help">${set.desc} · ${shortLevelLabel(level)} · ${set.verbs.length}개</p>
            <button class="primary-btn" data-test="${set.id}">✏️ 테스트 (${Math.min(IRREGULAR_QUIZ_SIZE, set.verbs.length)}문제)</button>
            ${groups
              .map(
                (g) => `
              <h3 class="irr-group-title">${g.label} <small>${g.desc}</small></h3>
              <ul class="irr-list">${g.verbs.map((v) => irregularVerbRow(v, set.id)).join("")}</ul>`
              )
              .join("")}
          </div>
        </details>`;
      }).join("")}
    </div>
  `;

  const screen = root.querySelector(".screen-irregular");
  root.querySelector("#backBtn").addEventListener("click", back);
  root.querySelector("#hideBtn").addEventListener("click", (e) => {
    irregularHideForms = !irregularHideForms;
    screen.classList.toggle("irr-hidden", irregularHideForms);
    screen.querySelectorAll(".irr-form.revealed").forEach((el) => el.classList.remove("revealed"));
    e.currentTarget.textContent = irregularHideForms ? "👀 모두 보이기" : "🙈 과거형 · 과거분사 가리기";
    e.currentTarget.setAttribute("aria-pressed", String(irregularHideForms));
    root.querySelector("#hideHelp").hidden = !irregularHideForms;
  });
  root.querySelectorAll("[data-form]").forEach((el) =>
    el.addEventListener("click", () => {
      if (irregularHideForms) el.classList.add("revealed");
    })
  );
  root.querySelectorAll("[data-speak]").forEach((btn) =>
    btn.addEventListener("click", () => {
      const [setId, base] = btn.dataset.speak.split("|");
      const v = findIrregularSet(setId).verbs.find((x) => x.base === base);
      speak(`${v.base}, ${v.past.replace(" / ", ", ")}, ${v.pp}`, { rate: 0.8 });
    })
  );
  root.querySelectorAll(".irr-set").forEach((el) =>
    el.addEventListener("toggle", () => {
      if (el.open) irregularOpenSet = el.dataset.set;
    })
  );
  root.querySelectorAll("[data-test]").forEach((btn) => btn.addEventListener("click", () => startTest(btn.dataset.test)));
}

;

/* ── js/screens/verbPattern.js ── */
// to부정사 · 동명사 목적어 동사: 원리 설명 → 묶음별 동사와 예문 → 테스트(빈칸 고르기 · 어느 묶음인지 고르기).
const VP_GROUP_TEST_SIZE = 8;
const VP_ALL_TEST_SIZE = 12;

const VP_REASONS = {
  "to-only": "앞으로 할 일(원함 · 계획 · 약속)을 말하는 동사라 to부정사만 써요.",
  "ing-only": "하고 있거나 한 행동 자체를 다루는 동사라 동명사(-ing)만 써요.",
  "both-same": "to부정사와 동명사 둘 다 쓸 수 있고 뜻도 같아요.",
};

function vpBase(item) {
  return (item.form.startsWith("to ") ? item.form : item.alt).slice(3);
}

function vpMarked(item) {
  return item.en.replace(item.form, `<mark class="lesson-key">${item.form}</mark>`);
}

function vpEntries(groupIds) {
  return VERB_PATTERN_GROUPS.filter((g) => groupIds.includes(g.id)).flatMap((g) => g.verbs.flatMap((v) => v.items.map((item) => ({ g, v, item }))));
}

function vpBlankQuestion({ g, v, item }) {
  const isTo = item.form.startsWith("to ");
  return {
    id: `vp|b|${v.v}|${item.form}`,
    drill: true,
    kind: "verbPattern",
    label: "빈칸에 알맞은 것을 고르세요",
    q: `${item.en.replace(item.form, "___")} (${vpBase(item)})`,
    ko: item.tr,
    choices: shuffle([item.form, item.alt]),
    correctAnswer: item.form,
    explain: `<b>${v.v}</b>(${v.ko}) + ${isTo ? "to부정사" : "동명사"}<br>${item.why || VP_REASONS[g.id]}`,
    summary: vpMarked(item),
    listenText: item.en,
    selectedAnswer: null,
  };
}

function vpKindQuestion({ g, v, item }) {
  return {
    id: `vp|k|${v.v}`,
    drill: true,
    kind: "verbPattern",
    label: "이 동사 뒤에 올 수 있는 것은?",
    q: v.v,
    big: true,
    ko: `${v.ko}`,
    choices: VERB_PATTERN_GROUPS.map((x) => x.short),
    correctAnswer: g.short,
    explain: `<b>${v.v}</b> → ${g.short}<br>${g.id === "both-diff" ? "to는 앞으로 할 일, -ing는 이미 한 일로 뜻이 달라져요." : VP_REASONS[g.id]}<br>예) ${vpMarked(item)}`,
    summary: `${v.v} → ${g.short}`,
    listenText: item.en,
    selectedAnswer: null,
  };
}

// 묶음 하나: 빈칸 문제(뜻이 같은 묶음은 어느 묶음인지 고르는 문제). 전체: 빈칸 8 + 묶음 고르기 4.
function buildVerbPatternQuestions(id) {
  if (id === "all") {
    const blanks = shuffle(vpEntries(["to-only", "ing-only", "both-diff"])).slice(0, 8).map(vpBlankQuestion);
    const usedVerbs = new Set(blanks.map((q) => q.id.split("|")[2]));
    const kinds = shuffle(VERB_PATTERN_GROUPS.flatMap((g) => g.verbs.map((v) => ({ g, v, item: v.items[0] }))))
      .filter((e) => !usedVerbs.has(e.v.v))
      .slice(0, VP_ALL_TEST_SIZE - blanks.length)
      .map(vpKindQuestion);
    return shuffle([...blanks, ...kinds]);
  }
  if (id === "both-same") {
    const mine = vpEntries(["both-same"]).map(vpKindQuestion);
    const others = shuffle(vpEntries(["to-only", "ing-only"])).slice(0, VP_GROUP_TEST_SIZE - mine.length).map(vpKindQuestion);
    return shuffle([...mine, ...others]);
  }
  const size = id === "both-diff" ? vpEntries([id]).length : VP_GROUP_TEST_SIZE;
  return shuffle(vpEntries([id])).slice(0, size).map(vpBlankQuestion);
}

function vpTestLabel(id) {
  if (id === "all") return "🔀 to부정사 · 동명사 종합";
  const g = VERB_PATTERN_GROUPS.find((x) => x.id === id);
  return `${g.emoji} ${g.title}`;
}

function vpTestSize(id) {
  if (id === "all") return VP_ALL_TEST_SIZE;
  if (id === "both-diff") return vpEntries([id]).length;
  return VP_GROUP_TEST_SIZE;
}

let vpOpenGroup = null;

function renderVerbPatternScreen(root, { profileName, startTest, back }) {
  const best = (id) => getSectionBest(profileName, "verbPattern", id);
  const openId = vpOpenGroup || (VERB_PATTERN_GROUPS.find((g) => !best(g.id)) || VERB_PATTERN_GROUPS[0]).id;
  const bestLabel = (id) => (best(id) ? `최고 ${best(id).correct}/${best(id).total}` : "");
  const allBest = best("all");

  root.innerHTML = `
    <div class="screen screen-vp">
      <button class="back-btn" id="backBtn">← 홈</button>
      <h1 class="title">🔀 to부정사 · 동명사</h1>
      <p class="subtitle">동사 뒤에 to가 올까, -ing가 올까?</p>

      <section class="lesson-section">
        <h2 class="section-title">💡 먼저 알아 둘 원리</h2>
        <p class="lesson-point-text">'수영하는 것을 좋아한다'처럼 동사 뒤에 <b>또 다른 동작</b>을 목적어로 쓰려면, 그 동작을 <b>to + 동사원형</b>(to부정사)이나 <b>동사ing</b>(동명사)로 바꿔야 해요. I like swim.은 틀리고 I like swimming. / I like to swim.이 맞아요.</p>
        <p class="lesson-point-text">문제는 <b>앞에 오는 동사가 어느 쪽을 좋아하는지</b>가 정해져 있다는 거예요. want는 to만, enjoy는 -ing만 받아요. 다행히 큰 원리가 있어요.</p>
        <div class="vp-principle">
          <div><b>to + 동사원형</b><span>➡️ 아직 안 한 일, 앞으로 할 일</span><small>I want <u>to go</u>. 가고 싶다 (아직 안 감)</small></div>
          <div><b>동사ing</b><span>🔄 하고 있거나 이미 한 일</span><small>I enjoy <u>going</u> there. 가는 걸 즐긴다 (실제로 감)</small></div>
        </div>
        <p class="lesson-point-text">이 원리로 대부분을 이해할 수 있어요. 아래 네 묶음을 차례로 보고, 묶음마다 테스트로 확인해 보세요.</p>
        <div class="table-scroll">
          <table class="note-table">
            <thead><tr><th>묶음</th><th>대표 동사</th></tr></thead>
            <tbody>${VERB_PATTERN_GROUPS.map((g) => `<tr><td>${g.emoji} ${g.short}</td><td>${g.verbs.slice(0, 5).map((v) => v.v).join(", ")} …</td></tr>`).join("")}</tbody>
          </table>
        </div>
        <button class="primary-btn" data-test="all">🧩 전체 섞어서 테스트 (${VP_ALL_TEST_SIZE}문제)${allBest ? ` · 최고 ${allBest.correct}/${allBest.total}` : ""}</button>
      </section>

      ${VERB_PATTERN_GROUPS.map(
        (g, gi) => `
      <details class="basic-grade vp-group" data-group="${g.id}" style="--accent:${g.color}" ${g.id === openId ? "open" : ""}>
        <summary class="basic-grade-title">${gi + 1}. ${g.emoji} ${g.title} <span class="basic-grade-count">${bestLabel(g.id) || `${g.verbs.length}개`}</span></summary>
        <div class="vp-body">
          <p class="vp-rule">${g.rule}</p>
          ${g.explain.map((p) => `<p class="lesson-point-text">${p}</p>`).join("")}
          <p class="vp-tip">📌 ${g.tip}</p>
          <ul class="vp-list">
            ${g.verbs
              .map(
                (v) => `
              <li class="vp-verb">
                <p class="vp-verb-head"><b>${v.v}</b> <span>${v.ko}</span></p>
                ${v.items
                  .map(
                    (item) => `
                <div class="lesson-example">
                  <button class="speak-btn" data-speak="${encodeURIComponent(item.en)}" aria-label="예문 듣기" ${speechSupported ? "" : "disabled"}>🔊</button>
                  <div>
                    <p class="lesson-example-en">${vpMarked(item)}</p>
                    <p class="lesson-example-ko">${item.tr}</p>
                    ${item.why ? `<p class="vp-why">👉 ${item.why}</p>` : ""}
                  </div>
                </div>`
                  )
                  .join("")}
              </li>`
              )
              .join("")}
          </ul>
          <button class="primary-btn" data-test="${g.id}">✏️ ${g.short} 테스트 (${vpTestSize(g.id)}문제)</button>
        </div>
      </details>`
      ).join("")}
    </div>
  `;

  root.querySelector("#backBtn").addEventListener("click", back);
  root.querySelectorAll("[data-speak]").forEach((btn) => btn.addEventListener("click", () => speak(decodeURIComponent(btn.dataset.speak))));
  root.querySelectorAll(".vp-group").forEach((el) =>
    el.addEventListener("toggle", () => {
      if (el.open) vpOpenGroup = el.dataset.group;
    })
  );
  root.querySelectorAll("[data-test]").forEach((btn) => btn.addEventListener("click", () => startTest(btn.dataset.test)));
}

;

/* ── js/screens/speaking.js ── */
// 따라 말하기: 대화 표현 예문을 듣고 따라 말하면 음성 인식으로 단어가 얼마나 맞았는지 보여 준다.
// 음성 인식이 안 되는 기기(아이폰 일부 등)에서는 듣고 따라 말한 뒤 스스로 체크한다.
const SpeechRecognitionApi = window.SpeechRecognition || window.webkitSpeechRecognition || null;
const SPEAKING_SIZE = 8;
const SPEAKING_PASS = 0.8;

function speakingSentences(groupId) {
  return TALK_TOPICS.filter((t) => t.group === groupId)
    .flatMap((t) => t.slides.flatMap((s) => s.examples))
    .filter((ex) => ex.en.split(" ").length <= 14 && !ex.en.includes("—"));
}

function buildSpeakingSession(groupId) {
  const seen = new Set();
  const items = shuffle(speakingSentences(groupId))
    .filter((ex) => !seen.has(ex.en) && seen.add(ex.en))
    .slice(0, SPEAKING_SIZE)
    .map((ex) => ({ ...ex, best: 0, heard: "", tries: 0 }));
  return { groupId, items, index: 0 };
}

const CONTRACTIONS = { "i'm": "i am", "you're": "you are", "it's": "it is", "that's": "that is", "don't": "do not", "can't": "can not", "cannot": "can not", "i'll": "i will", "we'll": "we will", "i'd": "i would", "let's": "let us", "isn't": "is not", "doesn't": "does not", "didn't": "did not", "won't": "will not", "what's": "what is", "there's": "there is", "we're": "we are", "they're": "they are", "he's": "he is", "she's": "she is", "i've": "i have", "you'll": "you will", "how's": "how is", "where's": "where is" };

// 인식기는 숫자를 "10"으로도 "ten"으로도 돌려줘서 숫자로 맞춘다.
const NUMBER_WORDS = Object.fromEntries("zero one two three four five six seven eight nine ten eleven twelve".split(" ").map((w, i) => [w, String(i)]));

function speakingWords(text) {
  return text
    .toLowerCase()
    .replace(/[’]/g, "'")
    .replace(/\b([ap])\.\s?m\.?/g, "$1m")
    .replace(/[^a-z0-9' ]+/g, " ")
    .split(/\s+/)
    .filter(Boolean)
    .flatMap((w) => (CONTRACTIONS[w] || NUMBER_WORDS[w] || w).split(" "));
}

// 목표 문장의 단어 중 순서대로 들린 단어 표시(LCS)
function speakingMatch(target, heard) {
  const a = speakingWords(target);
  const b = speakingWords(heard);
  const dp = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));
  for (let i = a.length - 1; i >= 0; i--) for (let j = b.length - 1; j >= 0; j--) dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
  const hit = new Array(a.length).fill(false);
  for (let i = 0, j = 0; i < a.length && j < b.length; ) {
    if (a[i] === b[j]) {
      hit[i] = true;
      i++;
      j++;
    } else if (dp[i + 1][j] >= dp[i][j + 1]) i++;
    else j++;
  }
  return { words: a, hit, score: a.length ? dp[0][0] / a.length : 0 };
}

function renderSpeakingListScreen(root, { profileName, start, back }) {
  root.innerHTML = `
    <div class="screen screen-speaking">
      <button class="back-btn" id="backBtn">← 홈</button>
      <h1 class="title">🎙️ 따라 말하기</h1>
      <p class="subtitle">듣고, 따라 말하고, 확인해요</p>
      <section class="lesson-section">
        <h2 class="section-title">이렇게 해요</h2>
        <div class="lesson-point"><span class="lesson-point-num">1</span><p class="lesson-point-text">🔊로 원어민 발음을 들어요. 🐢로 천천히 들을 수도 있어요.</p></div>
        <div class="lesson-point"><span class="lesson-point-num">2</span><p class="lesson-point-text">🎙️를 누르고 문장을 소리 내어 말해요.</p></div>
        <div class="lesson-point"><span class="lesson-point-num">3</span><p class="lesson-point-text">알아들은 단어는 초록색, 놓친 단어는 빨간색으로 보여요. <b>80% 이상</b>이면 통과!</p></div>
        ${SpeechRecognitionApi ? "" : `<p class="vp-tip">📱 이 기기·브라우저에서는 음성 인식이 되지 않아요. 듣고 따라 말한 뒤 스스로 ✅를 눌러 체크해요. (안드로이드 크롬, PC 크롬·엣지에서는 자동 채점이 돼요)</p>`}
      </section>
      ${(() => {
        const card = (g) => {
          const best = getSectionBest(profileName, "speaking", g.id);
          const count = new Set(speakingSentences(g.id).map((s) => s.en)).size;
          return `
          <button class="level-card" data-group="${g.id}" style="--accent:${g.color}">
            <span class="level-icon">🎙️</span>
            <span class="topic-text">
              <span class="level-label">${g.label}</span>
              <span class="topic-summary">문장 ${count}개 중 ${Math.min(SPEAKING_SIZE, count)}개</span>
            </span>
            <span class="level-best${best ? "" : " level-best-empty"}">${best ? `${best.correct}/${best.total}` : "시작"}</span>
          </button>`;
        };
        const { mine, others } = splitByMyLevel(TALK_GROUPS, (g) => TALK_GROUP_LEVELS[g.id] || [], myLevelOf(profileName));
        return levelSplitHtml(mine.map(card).join(""), others.map(card).join(""), others.length);
      })()}
    </div>
  `;
  root.querySelector("#backBtn").addEventListener("click", back);
  root.querySelectorAll("[data-group]").forEach((btn) => btn.addEventListener("click", () => start(btn.dataset.group)));
}

let activeRecognition = null;
// 마이크가 막히면(권한 거부 · 지원 안 함) 이번 실행 동안은 스스로 체크 버튼도 같이 보여 준다
let micBlocked = false;

// 마이크 권한을 켜는 방법 (기기별)
function micHelpHtml() {
  const ua = navigator.userAgent;
  const ios = /iPhone|iPad|iPod/.test(ua) || (/Macintosh/.test(ua) && navigator.maxTouchPoints > 1);
  const standalone = window.matchMedia?.("(display-mode: standalone)").matches || navigator.standalone;
  const how = ios
    ? "아이폰: <b>설정 → Safari → 마이크 → 허용</b>으로 바꾼 뒤 앱을 다시 열어요." + (standalone ? " 홈 화면 앱에서 계속 안 되면 Safari로 이 사이트를 열어서 해 보세요." : "")
    : /Android/.test(ua)
      ? standalone
        ? "안드로이드 앱: <b>휴대폰 설정 → 애플리케이션 → Chrome → 권한 → 마이크 → 허용</b> 후 다시 눌러요."
        : "안드로이드 크롬: 주소창 왼쪽 <b>🔒(또는 ⚙) → 권한 → 마이크 → 허용</b> 후 다시 눌러요."
      : "PC: 주소창 왼쪽 <b>🔒 → 마이크 → 허용</b> 후 페이지를 새로 고쳐요.";
  return `<p class="speak-heard">🎤 마이크를 쓸 수 없어요. ${how}<br>지금은 아래 <b>✅ 잘 말했어요</b>로 스스로 체크하며 계속할 수 있어요.</p>`;
}

function recognitionErrorHtml(error) {
  if (["not-allowed", "service-not-allowed", "audio-capture"].includes(error)) return micHelpHtml();
  if (error === "no-speech") return `<p class="speak-heard">🤫 소리가 들리지 않았어요. 다시 눌러 말해 보세요.</p>`;
  if (error === "network") return `<p class="speak-heard">📶 음성 인식은 인터넷이 필요해요. 연결을 확인하고 다시 해 보세요.</p>`;
  return `<p class="speak-heard">😥 음성 인식이 잠깐 안 됐어요. 다시 해 보세요.</p>`;
}

function stopRecognition() {
  if (activeRecognition) {
    try {
      activeRecognition.abort();
    } catch {}
    activeRecognition = null;
  }
}

function speakingResultHtml(item) {
  if (!item.tries) return "";
  if (!SpeechRecognitionApi || item.self) return `<p class="speak-score ${item.best >= SPEAKING_PASS ? "ok" : ""}">${item.best >= SPEAKING_PASS ? "✅ 잘 말했어요!" : "🔁 한 번 더 해 봐요"}</p>`;
  const m = speakingMatch(item.en, item.heard);
  const pct = Math.round(m.score * 100);
  return `
    <p class="speak-words">${m.words.map((w, i) => `<span class="${m.hit[i] ? "hit" : "miss"}">${w}</span>`).join(" ")}</p>
    <p class="speak-heard">들린 말: ${item.heard ? `"${item.heard}"` : "(아무 말도 듣지 못했어요)"}</p>
    <p class="speak-score ${m.score >= SPEAKING_PASS ? "ok" : ""}">${m.score >= SPEAKING_PASS ? "🎉" : "💪"} ${pct}%${item.best >= SPEAKING_PASS ? " · 통과!" : " · 80% 넘으면 통과"}</p>`;
}

function renderSpeakingSessionScreen(root, { session, group, actions }) {
  const item = session.items[session.index];
  const isLast = session.index === session.items.length - 1;
  const passed = session.items.filter((it) => it.best >= SPEAKING_PASS).length;

  root.innerHTML = `
    <div class="screen screen-quiz" style="--accent:${group.color}">
      ${quizTopbarHtml({ label: `🎙️ ${group.label}`, index: session.index, total: session.items.length, scoreText: `통과 ${passed}`, progressCount: session.index })}
      <div class="question-card speak-card">
        <p class="question-label">듣고 따라 말해 보세요</p>
        <p class="speak-emoji">${item.emoji || "💬"}</p>
        <p class="speak-target">${item.en}</p>
        <p class="grammar-question-ko">${item.ko}</p>
        <div class="listen-row">
          <button class="listen-btn" id="listenBtn" ${speechSupported ? "" : "disabled"}>🔊 듣기</button>
          <button class="listen-btn" id="slowBtn" ${speechSupported ? "" : "disabled"}>🐢 천천히</button>
        </div>
        ${recorderHtml("s:" + item.en)}
      </div>
      <div id="speakResult" class="speak-result" aria-live="polite">${speakingResultHtml(item)}</div>
      ${SpeechRecognitionApi ? `<button class="${micBlocked ? "secondary-btn" : "primary-btn"} speak-mic" id="micBtn">🎙️ ${micBlocked ? "마이크 다시 시도" : item.tries ? "다시 말하기" : "말하기"}</button>` : ""}
      ${!SpeechRecognitionApi || micBlocked ? `<div class="settings-actions"><button class="primary-btn" id="selfOkBtn">✅ 잘 말했어요</button><button class="secondary-btn" id="selfRetryBtn">🔁 다시 해 볼래요</button></div>` : ""}
      <button class="secondary-btn" id="nextBtn">${isLast ? "결과 보기" : item.tries ? "다음 문장 ▶" : "건너뛰기 ▶"}</button>
    </div>
  `;

  bindQuitConfirm(root, () => {
    stopRecognition();
    stopRecording();
    actions.quit();
  });
  bindRecorders(root);
  root.querySelector("#listenBtn").addEventListener("click", () => speak(item.en, { rate: 0.9 }));
  root.querySelector("#slowBtn").addEventListener("click", () => speak(item.en, { rate: 0.6 }));
  root.querySelector("#nextBtn").addEventListener("click", () => {
    stopRecognition();
    stopRecording();
    actions.next();
  });
  root.querySelector("#selfOkBtn")?.addEventListener("click", () => actions.selfCheck(true));
  root.querySelector("#selfRetryBtn")?.addEventListener("click", () => actions.selfCheck(false));

  const mic = root.querySelector("#micBtn");
  mic?.addEventListener("click", () => {
    if (activeRecognition) {
      stopRecognition();
      return;
    }
    stopSpeaking();
    const rec = new SpeechRecognitionApi();
    rec.lang = "en-US";
    rec.interimResults = false;
    rec.maxAlternatives = 3;
    activeRecognition = rec;
    mic.textContent = "👂 듣고 있어요… (누르면 멈춤)";
    mic.classList.add("listening");
    let got = false;
    rec.onresult = (e) => {
      got = true;
      // 후보 중 가장 잘 맞는 것을 고른다
      const alts = [...e.results[0]].map((r) => r.transcript);
      const heard = alts.sort((x, y) => speakingMatch(item.en, y).score - speakingMatch(item.en, x).score)[0];
      actions.heard(heard, speakingMatch(item.en, heard).score);
    };
    rec.onerror = (e) => {
      activeRecognition = null;
      mic.classList.remove("listening");
      if (["not-allowed", "service-not-allowed", "audio-capture"].includes(e.error) && !micBlocked) {
        // 스스로 체크 버튼이 보이게 다시 그린 뒤 안내를 띄운다
        micBlocked = true;
        actions.refresh();
        document.querySelector("#speakResult")?.insertAdjacentHTML("afterbegin", micHelpHtml());
        return;
      }
      root.querySelector("#speakResult").innerHTML = recognitionErrorHtml(e.error);
      mic.textContent = micBlocked ? "🎙️ 마이크 다시 시도" : "🎙️ 다시 말하기";
    };
    rec.onend = () => {
      activeRecognition = null;
      if (!got && mic.isConnected && mic.classList.contains("listening")) {
        mic.textContent = "🎙️ 다시 말하기";
        mic.classList.remove("listening");
      }
    };
    try {
      rec.start();
    } catch {
      activeRecognition = null;
      mic.classList.remove("listening");
      mic.textContent = "🎙️ 다시 말하기";
      root.querySelector("#speakResult").innerHTML = recognitionErrorHtml("");
    }
  });
}

;

/* ── js/screens/listening.js ── */
// 듣기 평가: 단계별 대화를 듣고 4지선다로 답한다. 문제 화면은 4지선다(mcQuiz)를 그대로 쓰고 question.dialog로 대화를 들려준다.
function findListeningSet(levelId) {
  return LISTENING_SETS.find((s) => s.levelId === levelId) || null;
}

function dialogScriptHtml(lines) {
  return `<div class="dialog-script">${lines.map(([s, t]) => `<p><span aria-label="${s === "W" ? "여자" : "남자"}">${s === "W" ? "👩" : "👨"}</span> ${t}</p>`).join("")}</div>`;
}

const LISTENING_TEST_SIZE = 5;

// 대화가 5개보다 많은 단계는 풀 때마다 5개를 무작위로 고른다
function buildListeningQuestions(levelId) {
  const set = findListeningSet(levelId);
  if (!set) return [];
  const picked = shuffle(set.items.map((item, i) => ({ item, i }))).slice(0, LISTENING_TEST_SIZE);
  return picked.map(({ item, i }) => ({
    id: `listen|${levelId}|${i}`,
    kind: "listening",
    label: "🎧 대화를 듣고 알맞은 답을 고르세요",
    q: item.q,
    ko: null,
    dialog: item.lines,
    choices: shuffle(item.choices),
    correctAnswer: item.choices[item.answer],
    explain: `${item.explain}${dialogScriptHtml(item.lines)}`,
    summary: item.q,
    listenText: null,
    selectedAnswer: null,
  }));
}

function renderListeningListScreen(root, { profileName, start, back }) {
  const myLevel = getPreferredLevel(profileName) || getLastWordLevel(profileName);
  root.innerHTML = `
    <div class="screen screen-listening">
      <button class="back-btn" id="backBtn">← 홈</button>
      <h1 class="title">🎧 듣기 평가</h1>
      <p class="subtitle">학교 듣기평가처럼 대화를 듣고 답해요</p>
      <section class="lesson-section">
        <h2 class="section-title">이렇게 풀어요</h2>
        <div class="lesson-point"><span class="lesson-point-num">1</span><p class="lesson-point-text">문제를 먼저 읽고, <b>무엇을 들어야 하는지</b>(시간? 장소? 기분?) 생각해요.</p></div>
        <div class="lesson-point"><span class="lesson-point-num">2</span><p class="lesson-point-text">대화는 문제를 열면 한 번 나와요. ▶로 다시 듣고, 🐢로 천천히 들을 수 있어요.</p></div>
        <div class="lesson-point"><span class="lesson-point-num">3</span><p class="lesson-point-text">답을 고르면 대화 대본과 해설을 볼 수 있어요. 👩 여자, 👨 남자예요.</p></div>
      </section>
      ${(() => {
        const card = (s) => {
          const level = levelById(s.levelId);
          const best = getSectionBest(profileName, "listening", s.levelId);
          return `
          <button class="level-card" data-level="${s.levelId}" style="--accent:${level.color}">
            <span class="level-icon">${level.emoji}</span>
            <span class="topic-text">
              <span class="level-label">${level.label}${s.levelId === myLevel ? " · 내 단계" : ""}</span>
              <span class="topic-summary">${s.items.length > LISTENING_TEST_SIZE ? `대화 ${s.items.length}개 중 ${LISTENING_TEST_SIZE}개` : `대화 ${s.items.length}개`}</span>
            </span>
            <span class="level-best${best ? "" : " level-best-empty"}">${ratioLabel(best)}</span>
          </button>`;
        };
        const { mine, others } = splitByMyLevel(LISTENING_SETS, (s) => [s.levelId], myLevel);
        return levelSplitHtml(mine.map(card).join(""), others.map(card).join(""), others.length);
      })()}
    </div>
  `;
  root.querySelector("#backBtn").addEventListener("click", back);
  root.querySelectorAll("[data-level]").forEach((btn) => btn.addEventListener("click", () => start(btn.dataset.level)));
}

;

/* ── js/screens/writing.js ── */
// 영작 연습: 단계별 문법 예문의 한국어 뜻을 보고 영어 문장 만들기.
// 🧩 단어 카드 배열(쉬움) 또는 ⌨️ 직접 쓰기(어려움). 학년(BASIC_GRADES)마다 8문장씩.
const WRITING_SIZE = 8;
let writingMode = "order";

function writingSentences(gradeId) {
  const seen = new Set();
  return BASIC_TOPICS.filter((t) => t.grade === gradeId).flatMap((t) =>
    t.slides
      .flatMap((s) => s.examples)
      .filter((ex) => {
        const n = ex.en.split(" ").length;
        const ok = n >= 3 && n <= 12 && !/[—/_()]|\.\.\.|…/.test(ex.en) && !seen.has(ex.en);
        if (ok) seen.add(ex.en);
        return ok;
      })
      .map((ex) => ({ en: ex.en, ko: ex.ko, emoji: ex.emoji, topic: `${t.emoji} ${t.title}` }))
  );
}

function buildWritingSession(gradeId, mode) {
  const items = shuffle(writingSentences(gradeId))
    .slice(0, WRITING_SIZE)
    .map((s) => {
      const words = s.en.split(" ");
      let order = shuffle(words.map((_, i) => i));
      // 섞었는데 그대로면 한 번 더 섞는다
      if (order.every((v, i) => v === i) && words.length > 1) order = [...order.slice(1), order[0]];
      return { ...s, words, pool: order, built: [], solved: false, firstTry: undefined, wrong: false, typed: "", revealed: false };
    });
  return { gradeId, mode, items, index: 0 };
}

function writingNormalize(text) {
  return text
    .toLowerCase()
    .replace(/[’]/g, "'")
    .replace(/[^a-z0-9' ]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

// 직접 쓰기 채점: 대소문자와 문장부호는 보지 않는다. 틀리면 내가 쓴 단어 중 맞은 자리(초록)와 다른 자리(빨강)만 보여 준다.
function writingDiffHtml(target, typed) {
  const a = writingNormalize(target).split(" ");
  const b = writingNormalize(typed).split(" ");
  const words = b.map((w, i) => `<span class="${a[i] === w ? "hit" : "miss"}">${w}</span>`).join(" ");
  const gap = a.length - b.length;
  return `${words}${gap > 0 ? ` <small>(단어 ${gap}개가 더 필요해요)</small>` : gap < 0 ? ` <small>(단어가 ${-gap}개 많아요)</small>` : ""}`;
}

function renderWritingListScreen(root, { profileName, start, back }) {
  const myLevel = getPreferredLevel(profileName) || getLastWordLevel(profileName);
  root.innerHTML = `
    <div class="screen screen-writing">
      <button class="back-btn" id="backBtn">← 홈</button>
      <h1 class="title">✍️ 영작 연습</h1>
      <p class="subtitle">한국어 뜻을 보고 영어 문장 만들기</p>
      <section class="lesson-section">
        <p class="lesson-point-text">단계별 문법에서 배운 예문으로 연습해요. 먼저 <b>🧩 단어 배열</b>로 익히고, 자신 있으면 <b>⌨️ 직접 쓰기</b>에 도전해요. 직접 쓰기는 대소문자와 문장부호를 따지지 않아요.</p>
        <div class="segmented segmented--wide" role="tablist">
          <button class="segmented-btn${writingMode === "order" ? " active" : ""}" data-mode="order" role="tab" aria-selected="${writingMode === "order"}">🧩 단어 배열</button>
          <button class="segmented-btn${writingMode === "type" ? " active" : ""}" data-mode="type" role="tab" aria-selected="${writingMode === "type"}">⌨️ 직접 쓰기</button>
        </div>
      </section>
      ${(() => {
        const card = (g) => {
          const count = writingSentences(g.id).length;
          if (!count) return "";
          const best = getSectionBest(profileName, "writing", `${writingMode}:${g.id}`);
          return `
          <button class="level-card" data-grade="${g.id}" style="--accent:${g.color}">
            <span class="level-icon">✍️</span>
            <span class="topic-text">
              <span class="level-label">${g.label}${g.levelId === myLevel ? " · 내 단계" : ""}</span>
              <span class="topic-summary">예문 ${count}개 중 ${Math.min(WRITING_SIZE, count)}개</span>
            </span>
            <span class="level-best${best ? "" : " level-best-empty"}">${ratioLabel(best)}</span>
          </button>`;
        };
        const { mine, others } = splitByMyLevel(BASIC_GRADES, (g) => [g.levelId], myLevel);
        return levelSplitHtml(mine.map(card).join(""), others.map(card).join(""), others.length);
      })()}
    </div>
  `;
  root.querySelector("#backBtn").addEventListener("click", back);
  root.querySelectorAll("[data-mode]").forEach((btn) =>
    btn.addEventListener("click", () => {
      writingMode = btn.dataset.mode;
      renderWritingListScreen(root, { profileName, start, back });
    })
  );
  root.querySelectorAll("[data-grade]").forEach((btn) => btn.addEventListener("click", () => start(btn.dataset.grade, writingMode)));
}

function renderWritingSessionScreen(root, { session, grade, actions }) {
  const item = session.items[session.index];
  const isLast = session.index === session.items.length - 1;
  const correct = session.items.filter((it) => it.firstTry).length;
  const done = item.solved || item.revealed;

  const orderHtml = `
    <div class="order-answer${item.solved ? " solved" : item.wrong ? " wrong" : ""}" aria-label="만든 문장">
      ${item.built.length ? item.built.map((w) => `<button class="order-tile in-answer" data-built="${w}" ${done ? "disabled" : ""}>${item.words[w]}</button>`).join("") : `<span class="order-placeholder">아래 단어를 차례로 눌러요</span>`}
    </div>
    <div class="order-pool">
      ${item.pool.map((w) => `<button class="order-tile" data-pool="${w}" ${done ? "disabled" : ""}>${item.words[w]}</button>`).join("")}
    </div>
    ${item.wrong ? `<p class="writing-feedback wrong">🤔 순서가 달라요. 단어를 눌러 빼고 다시 해 봐요.</p>` : ""}`;

  const typeHtml = `
    <input class="text-input writing-input" id="typeInput" type="text" autocomplete="off" autocapitalize="sentences" spellcheck="false" placeholder="영어 문장을 써 보세요" value="${item.typed.replace(/"/g, "&quot;")}" ${done ? "disabled" : ""} />
    ${item.wrong && !done ? `<p class="writing-feedback wrong">🤔 다른 곳이 있어요: ${writingDiffHtml(item.en, item.typed)}</p>` : ""}
    ${done ? "" : `<div class="settings-actions"><button class="primary-btn" id="checkBtn">확인</button><button class="secondary-btn" id="hintBtn">💡 첫 단어 보기</button></div>`}`;

  root.innerHTML = `
    <div class="screen screen-quiz" style="--accent:${grade.color}">
      ${quizTopbarHtml({ label: `✍️ ${grade.label}`, index: session.index, total: session.items.length, scoreText: `맞힘 ${correct}`, progressCount: session.index })}
      <div class="question-card">
        <p class="question-label">${item.topic}</p>
        <p class="writing-ko">${item.emoji || ""} ${item.ko}</p>
        ${item.hint ? `<p class="writing-hint">💡 ${item.words[0]} …</p>` : ""}
      </div>
      ${session.mode === "order" ? orderHtml : typeHtml}
      ${
        done
          ? `<div class="result-banner ${item.solved ? "correct" : "wrong"}" role="status">${item.solved ? "🎉 맞았어요!" : "📖 정답을 확인해요"}</div>
             <div class="explain-card"><p class="grammar-question">${item.en}</p>
             <button class="listen-btn" id="listenBtn" ${speechSupported ? "" : "disabled"}>🔊 문장 듣기</button></div>
             <button class="primary-btn" id="nextBtn">${isLast ? "결과 보기" : "다음 문장"}</button>`
          : `<button class="secondary-btn" id="giveUpBtn">정답 보기</button>`
      }
    </div>
  `;

  bindQuitConfirm(root, actions.quit);
  root.querySelectorAll("[data-pool]").forEach((b) => b.addEventListener("click", () => actions.tapPool(Number(b.dataset.pool))));
  root.querySelectorAll("[data-built]").forEach((b) => b.addEventListener("click", () => actions.tapBuilt(Number(b.dataset.built))));
  const input = root.querySelector("#typeInput");
  if (input && !done) {
    input.focus({ preventScroll: true });
    input.addEventListener("keydown", (e) => {
      if (e.key === "Enter") actions.checkTyped(input.value);
    });
  }
  root.querySelector("#checkBtn")?.addEventListener("click", () => actions.checkTyped(input.value));
  root.querySelector("#hintBtn")?.addEventListener("click", () => actions.hint(input.value));
  root.querySelector("#giveUpBtn")?.addEventListener("click", actions.reveal);
  root.querySelector("#listenBtn")?.addEventListener("click", () => speak(item.en));
  const next = root.querySelector("#nextBtn");
  next?.addEventListener("click", actions.next);
  next?.focus({ preventScroll: true });
}

;

/* ── js/screens/wordParts.js ── */
// 숙어 · 구동사와 접두사 · 접미사: 묶음별 설명 → 예문 → 10문제 테스트. 화면 틀은 둘이 같이 쓴다.
const WORD_PARTS_TEST_SIZE = 10;

// 뜻이 비슷해서 서로 오답 보기로 내면 안 되는 접사
const AFFIX_LOOKALIKE = [["un-", "dis-", "in- / im-"], ["-tion / -sion", "-ment", "-ness"], ["-ful", "-ous"]];

function lookalike(a, b) {
  return AFFIX_LOOKALIKE.some((g) => g.includes(a) && g.includes(b));
}

function pickDistractors(correct, pool, n = 3) {
  return shuffle(pool.filter((x) => x !== correct)).filter((x, i, arr) => arr.indexOf(x) === i).slice(0, n);
}

function idiomQuestion(set, item, kind) {
  const others = set.items.filter((x) => x !== item);
  if (kind === "meaning") {
    return {
      id: `idiom|${set.id}|${item.e}|m`,
      kind: "idiom",
      label: "이 표현의 뜻은?",
      q: item.e,
      big: true,
      ko: `예) ${item.en}`,
      choices: shuffle([item.ko, ...pickDistractors(item.ko, others.map((x) => x.ko))]),
      correctAnswer: item.ko,
      explain: `<b>${item.e}</b> = ${item.ko}<br>${item.en}<br>${item.tr}`,
      summary: `${item.e} = ${item.ko}`,
      listenText: item.en,
      selectedAnswer: null,
    };
  }
  return {
    id: `idiom|${set.id}|${item.e}|e`,
    kind: "idiom",
    label: "뜻에 맞는 표현은?",
    q: item.ko,
    big: true,
    ko: item.tr,
    choices: shuffle([item.e, ...pickDistractors(item.e, others.map((x) => x.e))]),
    correctAnswer: item.e,
    explain: `<b>${item.e}</b> = ${item.ko}<br>${item.en}`,
    summary: `${item.ko} = ${item.e}`,
    listenText: item.en,
    selectedAnswer: null,
  };
}

function buildIdiomQuestions(setId) {
  const set = IDIOM_SETS.find((s) => s.id === setId);
  return shuffle(set.items)
    .slice(0, WORD_PARTS_TEST_SIZE)
    .map((item, i) => idiomQuestion(set, item, i % 2 ? "meaning" : "expr"));
}

function affixWordQuestion(set, affix, w) {
  const pool = set.items.flatMap((a) => a.words.map((x) => x.meaning));
  return {
    id: `affix|${w.word}`,
    kind: "affix",
    label: "조각으로 나누어 뜻을 짐작해 보세요",
    q: w.word,
    big: true,
    ko: `${affix.a} (${affix.ko}) + ${w.base}`,
    choices: shuffle([w.meaning, ...pickDistractors(w.meaning, pool)]),
    correctAnswer: w.meaning,
    explain: `<b>${w.word}</b> = ${affix.a.startsWith("-") ? `${w.base} + ${affix.a}` : `${affix.a} + ${w.base}`} → ${w.meaning}<br>${affix.a}: ${affix.ko}. ${affix.note}`,
    summary: `${w.word} = ${w.meaning}`,
    listenText: w.word,
    selectedAnswer: null,
  };
}

function affixMeaningQuestion(set, affix) {
  const pool = set.items.filter((x) => x !== affix && !lookalike(x.a, affix.a)).map((x) => x.ko);
  return {
    id: `affix|${affix.a}`,
    kind: "affix",
    label: "이 조각의 뜻은?",
    q: affix.a,
    big: true,
    ko: `예) ${affix.words.map((w) => w.word).join(", ")}`,
    choices: shuffle([affix.ko, ...pickDistractors(affix.ko, pool)]),
    correctAnswer: affix.ko,
    explain: `<b>${affix.a}</b> = ${affix.ko}<br>${affix.words.map((w) => `${w.word}(${w.meaning})`).join(", ")}`,
    summary: `${affix.a} = ${affix.ko}`,
    listenText: null,
    selectedAnswer: null,
  };
}

function buildAffixQuestions(setId) {
  const set = AFFIX_SETS.find((s) => s.id === setId);
  const words = shuffle(set.items.flatMap((a) => a.words.map((w) => ({ a, w })))).slice(0, 7).map(({ a, w }) => affixWordQuestion(set, a, w));
  const metas = shuffle(set.items).slice(0, WORD_PARTS_TEST_SIZE - words.length).map((a) => affixMeaningQuestion(set, a));
  return shuffle([...words, ...metas]);
}

let wordPartsOpen = {};

// config: { key, title, subtitle, introHtml, sets, section, itemsHtml(set) }
function renderWordPartsScreen(root, { profileName, config, startTest, back }) {
  const best = (id) => getSectionBest(profileName, config.section, id);
  const myLevel = getPreferredLevel(profileName) || getLastWordLevel(profileName);
  const openId = wordPartsOpen[config.key] || (config.sets.find((s) => s.levelId === myLevel) || config.sets.find((s) => !best(s.id)) || config.sets[0]).id;

  root.innerHTML = `
    <div class="screen screen-vp">
      <button class="back-btn" id="backBtn">← 홈</button>
      <h1 class="title">${config.title}</h1>
      <p class="subtitle">${config.subtitle}</p>
      <section class="lesson-section">${config.introHtml}</section>
      ${config.sets
        .map((set) => {
          const level = levelById(set.levelId);
          const b = best(set.id);
          return `
      <details class="basic-grade vp-group" data-set="${set.id}" style="--accent:${level.color}" ${set.id === openId ? "open" : ""}>
        <summary class="basic-grade-title">${set.emoji} ${set.title} <span class="basic-grade-count">${b ? `최고 ${b.correct}/${b.total}` : `${set.items.length}개`}</span></summary>
        <div class="vp-body">
          <p class="lesson-point-text">${set.intro}</p>
          <ul class="vp-list">${config.itemsHtml(set)}</ul>
          <button class="primary-btn" data-test="${set.id}">✏️ 테스트 (${WORD_PARTS_TEST_SIZE}문제)</button>
        </div>
      </details>`;
        })
        .join("")}
    </div>
  `;

  root.querySelector("#backBtn").addEventListener("click", back);
  root.querySelectorAll("[data-speak]").forEach((btn) => btn.addEventListener("click", () => speak(decodeURIComponent(btn.dataset.speak))));
  root.querySelectorAll(".vp-group").forEach((el) =>
    el.addEventListener("toggle", () => {
      if (el.open) wordPartsOpen[config.key] = el.dataset.set;
    })
  );
  root.querySelectorAll("[data-test]").forEach((btn) => btn.addEventListener("click", () => startTest(btn.dataset.test)));
}

const speakBtnHtml = (text) => `<button class="speak-btn" data-speak="${encodeURIComponent(text)}" aria-label="듣기" ${speechSupported ? "" : "disabled"}>🔊</button>`;

const IDIOM_SCREEN = {
  key: "idiom",
  title: "🧩 숙어 · 생활 표현",
  subtitle: "덩어리로 외우는 표현",
  section: "idiom",
  sets: IDIOM_SETS,
  introHtml: `<p class="lesson-point-text">숙어는 <b>여러 단어가 모여 새로운 뜻</b>을 만드는 표현이에요. give(주다) + up(위로)을 더해도 '포기하다'라는 뜻은 나오지 않죠. 그래서 <b>예문과 함께 덩어리째</b> 외우는 게 가장 좋아요. 🔊로 예문을 듣고 소리 내어 따라 읽어 보세요.</p>`,
  itemsHtml: (set) =>
    set.items
      .map(
        (it) => `
      <li class="vp-verb">
        <p class="vp-verb-head"><b>${it.e}</b> <span>${it.ko}</span></p>
        <div class="lesson-example">${speakBtnHtml(it.en)}<div><p class="lesson-example-en">${it.en}</p><p class="lesson-example-ko">${it.tr}</p></div></div>
      </li>`
      )
      .join(""),
};

const AFFIX_SCREEN = {
  key: "affix",
  title: "🔤 접두사 · 접미사",
  subtitle: "단어 조각으로 뜻 짐작하기",
  section: "affix",
  sets: AFFIX_SETS,
  introHtml: `<p class="lesson-point-text">긴 영어 단어는 대부분 <b>앞 조각(접두사) + 뿌리 단어 + 뒤 조각(접미사)</b>으로 되어 있어요. 예를 들어 <b>un + believe + able</b> = unbelievable(믿을 수 없는)이에요. 조각의 뜻만 알아도 처음 보는 단어의 뜻을 짐작할 수 있어서, 독해할 때 큰 힘이 돼요.</p>`,
  itemsHtml: (set) =>
    set.items
      .map(
        (a) => `
      <li class="vp-verb">
        <p class="vp-verb-head"><b>${a.a}</b> <span>${a.ko}</span></p>
        <p class="lesson-point-text">${a.note}</p>
        ${a.words
          .map(
            (w) => `<div class="lesson-example">${speakBtnHtml(w.word)}<div><p class="lesson-example-en">${w.base} → <b>${w.word}</b></p><p class="lesson-example-ko">${w.meaning}</p></div></div>`
          )
          .join("")}
      </li>`
      )
      .join(""),
};

;

/* ── js/screens/exam.js ── */
// 단원 모의고사: 학년(BASIC_GRADES)마다 20문제, 듣기 · 문법 · 어휘 · 동사 · 숙어를 섞어 100점 만점으로 채점한다.
const EXAM_SIZE = 20;

function examPlan(levelId) {
  const rank = levelRank(levelId);
  if (rank <= levelRank("elementary-low")) return { listening: 2, grammar: 10, word: 8 };
  if (rank < levelRank("middle")) return { listening: 2, grammar: 9, word: 6, irregular: 3 };
  return { listening: 2, grammar: 8, word: 5, irregular: 2, verb: 3 };
}

const EXAM_AREAS = { listening: "듣기", grammar: "문법", word: "어휘", irregular: "불규칙 동사", verb: "동사 · 숙어" };

function tagExam(q, area) {
  return { ...q, examArea: area, summary: `<small>[${EXAM_AREAS[area]}]</small> ${q.summary}` };
}

function buildExamQuestions(gradeId) {
  const grade = BASIC_GRADES.find((g) => g.id === gradeId);
  const levelId = grade.levelId;
  const plan = examPlan(levelId);
  const parts = [];

  parts.push(...shuffle(buildListeningQuestions(levelId)).slice(0, plan.listening).map((q) => tagExam(q, "listening")));

  const grammarPool = BASIC_TOPICS.filter((t) => t.grade === gradeId).flatMap((t) => t.practice.map((p, i) => (p.type === "choose" ? [t, i] : null)).filter(Boolean));
  parts.push(...shuffle(grammarPool).slice(0, plan.grammar).map(([t, i]) => tagExam(basicChooseQuestion(t, i), "grammar")));

  parts.push(...shuffle(WORD_BANK[levelId]).slice(0, plan.word).map((w) => tagExam(wordToMcQuestion(w, levelId), "word")));

  if (plan.irregular) {
    const sets = IRREGULAR_SETS.filter((s) => levelRank(s.levelId) <= levelRank(levelId));
    const verbs = shuffle(sets.flatMap((s) => s.verbs.map((v) => [v, s])));
    parts.push(...verbs.slice(0, plan.irregular).map(([v, s], i) => tagExam(irregularQuestion(v, s, i % 2 ? "pp" : "past"), "irregular")));
  }
  if (plan.verb) {
    const idiomSet = IDIOM_SETS.find((s) => s.levelId === levelId) || IDIOM_SETS[0];
    const vp = shuffle(vpEntries(["to-only", "ing-only", "both-diff"])).slice(0, 2).map(vpBlankQuestion);
    const idiom = shuffle(idiomSet.items).slice(0, plan.verb - vp.length).map((item) => idiomQuestion(idiomSet, item, "meaning"));
    parts.push(...[...vp, ...idiom].map((q) => tagExam(q, "verb")));
  }

  // 시험지처럼 듣기를 먼저, 나머지는 섞는다. 모자라면 문법 문제로 채운다.
  const listening = parts.filter((q) => q.examArea === "listening");
  let rest = shuffle(parts.filter((q) => q.examArea !== "listening"));
  const extra = shuffle(grammarPool).filter(([t, i]) => !rest.some((q) => q.id === `basic|${t.id}|${i}`));
  while (listening.length + rest.length < EXAM_SIZE && extra.length) {
    const [t, i] = extra.shift();
    rest.push(tagExam(basicChooseQuestion(t, i), "grammar"));
  }
  return [...listening, ...rest].slice(0, EXAM_SIZE);
}

function examAreaReport(questions) {
  const areas = {};
  for (const q of questions) {
    const a = (areas[q.examArea] ||= { ok: 0, total: 0 });
    a.total += 1;
    if (q.selectedAnswer === q.correctAnswer) a.ok += 1;
  }
  return Object.keys(EXAM_AREAS)
    .filter((k) => areas[k])
    .map((k) => `${EXAM_AREAS[k]} ${areas[k].ok}/${areas[k].total}`)
    .join(" · ");
}

function renderExamListScreen(root, { profileName, start, back }) {
  const myLevel = getPreferredLevel(profileName) || getLastWordLevel(profileName);
  root.innerHTML = `
    <div class="screen screen-exam">
      <button class="back-btn" id="backBtn">← 홈</button>
      <h1 class="title">📝 단원 모의고사</h1>
      <p class="subtitle">학년별 20문제 · 100점 만점</p>
      <section class="lesson-section">
        <p class="lesson-point-text">중간 · 기말고사처럼 <b>듣기 → 문법 · 어휘 · 동사 · 숙어</b>를 섞어 20문제를 풀어요. 한 문제에 5점이에요. 끝나면 영역별 점수를 보여 주고, 틀린 문제는 오답노트에 모여요.</p>
      </section>
      ${(() => {
        const card = (g) => {
          const best = getSectionBest(profileName, "exam", g.id);
          return `
          <button class="level-card" data-grade="${g.id}" style="--accent:${g.color}">
            <span class="level-icon">📝</span>
            <span class="topic-text">
              <span class="level-label">${g.label}${g.levelId === myLevel ? " · 내 단계" : ""}</span>
              <span class="topic-summary">${Object.entries(examPlan(g.levelId)).map(([k, n]) => `${EXAM_AREAS[k]} ${n}`).join(" · ")}</span>
            </span>
            <span class="level-best${best ? "" : " level-best-empty"}">${best ? `${Math.round((best.correct / best.total) * 100)}점` : "시작"}</span>
          </button>`;
        };
        const { mine, others } = splitByMyLevel(BASIC_GRADES, (g) => [g.levelId], myLevel);
        return levelSplitHtml(mine.map(card).join(""), others.map(card).join(""), others.length);
      })()}
    </div>
  `;
  root.querySelector("#backBtn").addEventListener("click", back);
  root.querySelectorAll("[data-grade]").forEach((btn) => btn.addEventListener("click", () => start(btn.dataset.grade)));
}

;

/* ── js/screens/goals.js ── */
// 이번 주 목표와 과제: 부모님이 아이 프로필에 목표(문제 수 · 공부한 날 · 오늘의 학습)와 과제를 정해 주면 진행률을 보여 준다.
const GOAL_COUNTS = [
  { key: "answers", emoji: "✏️", label: "문제 풀기", unit: "문제", options: [0, 30, 50, 100, 150, 200, 300] },
  { key: "days", emoji: "📅", label: "공부한 날", unit: "일", options: [0, 2, 3, 4, 5, 6, 7] },
  { key: "daily", emoji: "☀️", label: "오늘의 학습 완료", unit: "번", options: [0, 2, 3, 4, 5, 6, 7] },
];
const TASK_PASS = 0.8;

const passed = (best, ratio = TASK_PASS) => !!best && best.correct / best.total >= ratio;

// 과제 목록: id → { group, label, done(profileName) }
function goalTaskCatalog() {
  const list = [];
  const add = (group, id, label, done) => list.push({ group, id, label, done });
  for (const g of BASIC_GRADES) {
    const topics = BASIC_TOPICS.filter((t) => t.grade === g.id);
    add("📘 단계별 문법", `basics|${g.id}`, `${g.label} 주제 모두 끝내기 (${topics.length}개)`, (p) => topics.every((t) => getSectionBest(p, "basics", t.id)));
  }
  for (const s of IRREGULAR_SETS) add("🔁 불규칙 동사", `irregular|${s.id}`, `${s.title} 테스트 80점 이상`, (p) => passed(getSectionBest(p, "irregular", s.id)));
  for (const g of VERB_PATTERN_GROUPS) add("🔀 to부정사 · 동명사", `verbPattern|${g.id}`, `${g.title} 테스트 80점 이상`, (p) => passed(getSectionBest(p, "verbPattern", g.id)));
  add("🔀 to부정사 · 동명사", "verbPattern|all", "종합 테스트 80점 이상", (p) => passed(getSectionBest(p, "verbPattern", "all")));
  for (const s of IDIOM_SETS) add("🧩 숙어 · 구동사", `idiom|${s.id}`, `${s.title} 테스트 80점 이상`, (p) => passed(getSectionBest(p, "idiom", s.id)));
  for (const s of AFFIX_SETS) add("🔠 접두사 · 접미사", `affix|${s.id}`, `${s.title.split(":")[0]} 테스트 80점 이상`, (p) => passed(getSectionBest(p, "affix", s.id)));
  for (const s of LISTENING_SETS) add("🎧 듣기 평가", `listening|${s.levelId}`, `${levelById(s.levelId).label} 80점 이상`, (p) => passed(getSectionBest(p, "listening", s.levelId)));
  for (const g of TALK_GROUPS) add("🎙️ 따라 말하기", `speaking|${g.id}`, `${g.label} 8문장 중 6개 통과`, (p) => passed(getSectionBest(p, "speaking", g.id), 0.75));
  for (const g of BASIC_GRADES) add("✍️ 영작 연습", `writing|${g.id}`, `${g.label} 단어 배열 80점 이상`, (p) => passed(getSectionBest(p, "writing", `order:${g.id}`)));
  for (const g of BASIC_GRADES) add("📝 단원 모의고사", `exam|${g.id}`, `${g.label} 모의고사 80점 이상`, (p) => passed(getSectionBest(p, "exam", g.id)));
  return list;
}

function goalSummary(profileName) {
  const goals = getGoals(profileName);
  const week = getWeekProgress(profileName);
  const catalog = goalTaskCatalog();
  const counts = GOAL_COUNTS.filter((c) => goals.counts[c.key] > 0).map((c) => ({ ...c, target: goals.counts[c.key], value: week[c.key] }));
  const tasks = goals.tasks.map((id) => catalog.find((t) => t.id === id)).filter(Boolean).map((t) => ({ ...t, isDone: t.done(profileName) }));
  const total = counts.length + tasks.length;
  const done = counts.filter((c) => c.value >= c.target).length + tasks.filter((t) => t.isDone).length;
  return { goals, counts, tasks, total, done, catalog };
}

function renderGoalsScreen(root, { profileName, back }) {
  const s = goalSummary(profileName);
  const groups = [...new Set(s.catalog.map((t) => t.group))];

  root.innerHTML = `
    <div class="screen screen-goals">
      <button class="back-btn" id="backBtn">← 홈</button>
      <h1 class="title">🎯 이번 주 목표</h1>
      <p class="subtitle">${profileName}님 · 월요일부터 일요일까지</p>

      <section class="settings-card">
        <h2 class="section-title">진행 상황 ${s.total ? `${s.done} / ${s.total}` : ""}</h2>
        ${
          s.total === 0
            ? `<p class="settings-help">아직 목표가 없어요. 아래에서 이번 주 목표를 정해 보세요. 아이 목표는 부모님이 함께 정해 주면 좋아요.</p>`
            : `<ul class="bar-list">
            ${s.counts
              .map((c) => {
                const pct = Math.min(100, Math.round((c.value / c.target) * 100));
                return `<li><span class="bar-name">${c.emoji} ${c.label}</span>${barHtml(pct, c.value >= c.target ? "var(--correct)" : "var(--primary)")}<span class="bar-value">${c.value}/${c.target}${c.unit}</span></li>`;
              })
              .join("")}
          </ul>
          <ul class="goal-tasks">
            ${s.tasks.map((t) => `<li class="${t.isDone ? "done" : ""}"><span>${t.isDone ? "✅" : "⬜"}</span><span>${t.group.split(" ")[0]} ${t.label}</span><button class="wrong-remove" data-remove="${t.id}" aria-label="과제 빼기">빼기</button></li>`).join("")}
          </ul>
          ${s.total > 0 && s.done === s.total ? `<p class="goal-cheer">🎉 이번 주 목표를 모두 이뤘어요!</p>` : ""}`
        }
      </section>

      <section class="settings-card">
        <h2 class="section-title">목표 정하기</h2>
        ${GOAL_COUNTS.map(
          (c) => `
          <label class="goal-row">
            <span>${c.emoji} 이번 주 ${c.label}</span>
            <select class="text-input goal-select" data-count="${c.key}">
              ${c.options.map((o) => `<option value="${o}" ${s.goals.counts[c.key] === o ? "selected" : ""}>${o === 0 ? "목표 없음" : `${o}${c.unit}`}</option>`).join("")}
            </select>
          </label>`
        ).join("")}
        <label class="goal-row goal-row--col">
          <span>📌 과제 추가</span>
          <select class="text-input" id="taskSelect">
            <option value="">과제를 골라요</option>
            ${groups
              .map(
                (g) => `<optgroup label="${g}">${s.catalog
                  .filter((t) => t.group === g && !s.goals.tasks.includes(t.id))
                  .map((t) => `<option value="${t.id}">${t.label}</option>`)
                  .join("")}</optgroup>`
              )
              .join("")}
          </select>
        </label>
        <button class="primary-btn" id="addTaskBtn">＋ 과제 추가</button>
        <p class="settings-help">과제는 해당 테스트에서 80점 이상(따라 말하기는 6문장 통과)을 받으면 저절로 ✅가 돼요. 숫자 목표는 매주 월요일에 새로 셉니다.</p>
      </section>
    </div>
  `;

  const save = (goals) => {
    setGoals(profileName, goals);
    renderGoalsScreen(root, { profileName, back });
  };
  root.querySelector("#backBtn").addEventListener("click", back);
  root.querySelectorAll("[data-count]").forEach((sel) =>
    sel.addEventListener("change", () => save({ ...s.goals, counts: { ...s.goals.counts, [sel.dataset.count]: Number(sel.value) } }))
  );
  root.querySelector("#addTaskBtn").addEventListener("click", () => {
    const id = root.querySelector("#taskSelect").value;
    if (id) save({ ...s.goals, tasks: [...s.goals.tasks, id] });
  });
  root.querySelectorAll("[data-remove]").forEach((btn) => btn.addEventListener("click", () => save({ ...s.goals, tasks: s.goals.tasks.filter((t) => t !== btn.dataset.remove) })));
}

;

/* ── js/screens/crossword.js ── */
// 가로세로 낱말 퀴즈: 열 때마다 내 단계 단어장에서 단어를 무작위로 뽑아 새 퍼즐을 만든다.
// 힌트는 한국어 뜻, 칸에는 영어 철자를 쓴다.
const CROSSWORD_MAX = 11; // 가로 · 세로 최대 칸 수 (휴대폰 화면에 맞춤)
const CROSSWORD_TARGET = 10; // 목표 단어 수
const CROSSWORD_MIN = 6;

function crosswordPool(levelId) {
  const maxLen = levelId === "elementary-low" ? 6 : 9;
  return (WORD_BANK[levelId] || []).filter((w) => /^[a-z]+$/.test(w.word) && w.word.length >= 3 && w.word.length <= maxLen);
}

function tryCrossword(words) {
  const cells = new Map(); // "r,c" → { ch, dirs:Set }
  const placed = [];
  const key = (r, c) => `${r},${c}`;
  let bounds = null;

  const fits = (word, r, c, dir) => {
    const [dr, dc] = dir === "across" ? [0, 1] : [1, 0];
    const before = cells.get(key(r - dr, c - dc));
    const after = cells.get(key(r + dr * word.length, c + dc * word.length));
    if (before || after) return -1;
    let cross = 0;
    for (let i = 0; i < word.length; i++) {
      const rr = r + dr * i;
      const cc = c + dc * i;
      const cell = cells.get(key(rr, cc));
      if (cell) {
        if (cell.ch !== word[i] || cell.dirs.has(dir)) return -1;
        cross += 1;
      } else {
        // 옆 칸이 비어 있어야 엉뚱한 단어가 붙지 않는다
        if (cells.get(key(rr + dc, cc + dr)) || cells.get(key(rr - dc, cc - dr))) return -1;
      }
    }
    if (bounds) {
      const minR = Math.min(bounds.minR, r);
      const minC = Math.min(bounds.minC, c);
      const maxR = Math.max(bounds.maxR, r + dr * (word.length - 1));
      const maxC = Math.max(bounds.maxC, c + dc * (word.length - 1));
      if (maxR - minR + 1 > CROSSWORD_MAX || maxC - minC + 1 > CROSSWORD_MAX) return -1;
    }
    return cross;
  };

  const put = (w, r, c, dir) => {
    const [dr, dc] = dir === "across" ? [0, 1] : [1, 0];
    for (let i = 0; i < w.word.length; i++) {
      const k = key(r + dr * i, c + dc * i);
      const cell = cells.get(k) || { ch: w.word[i], dirs: new Set() };
      cell.dirs.add(dir);
      cells.set(k, cell);
    }
    const endR = r + dr * (w.word.length - 1);
    const endC = c + dc * (w.word.length - 1);
    bounds = bounds
      ? { minR: Math.min(bounds.minR, r), minC: Math.min(bounds.minC, c), maxR: Math.max(bounds.maxR, endR), maxC: Math.max(bounds.maxC, endC) }
      : { minR: r, minC: c, maxR: endR, maxC: endC };
    placed.push({ data: w, word: w.word, r, c, dir });
  };

  const [first, ...rest] = words;
  put(first, 0, 0, Math.random() < 0.5 ? "across" : "down");
  for (const w of rest) {
    if (placed.length >= CROSSWORD_TARGET) break;
    const options = [];
    for (const [k, cell] of cells) {
      const [cr, cc] = k.split(",").map(Number);
      for (let i = 0; i < w.word.length; i++) {
        if (w.word[i] !== cell.ch) continue;
        for (const dir of ["across", "down"]) {
          if (cell.dirs.has(dir)) continue;
          const r = dir === "down" ? cr - i : cr;
          const c = dir === "across" ? cc - i : cc;
          const cross = fits(w.word, r, c, dir);
          if (cross > 0) options.push({ r, c, dir, cross });
        }
      }
    }
    if (!options.length) continue;
    const best = Math.max(...options.map((o) => o.cross));
    const pick = shuffle(options.filter((o) => o.cross === best))[0];
    put(w, pick.r, pick.c, pick.dir);
  }
  return { placed, bounds };
}

function buildCrossword(levelId) {
  const pool = crosswordPool(levelId);
  let best = null;
  for (let attempt = 0; attempt < 30; attempt++) {
    // 긴 단어를 먼저 놓으면 잘 엮인다
    const words = shuffle(pool).slice(0, 40).sort((a, b) => b.word.length - a.word.length + (Math.random() - 0.5) * 3);
    const result = tryCrossword(words);
    const area = (result.bounds.maxR - result.bounds.minR + 1) * (result.bounds.maxC - result.bounds.minC + 1);
    const score = result.placed.length * 100 - area;
    if (!best || score > best.score) best = { ...result, score };
    if (result.placed.length >= CROSSWORD_TARGET && area <= 100) break;
  }
  if (best.placed.length < CROSSWORD_MIN) return null;

  const { minR, minC, maxR, maxC } = best.bounds;
  const rows = maxR - minR + 1;
  const cols = maxC - minC + 1;
  const grid = Array.from({ length: rows }, () => new Array(cols).fill(null));
  const entries = best.placed.map((p) => ({ ...p, r: p.r - minR, c: p.c - minC }));
  for (const e of entries) {
    for (let i = 0; i < e.word.length; i++) {
      const r = e.r + (e.dir === "down" ? i : 0);
      const c = e.c + (e.dir === "across" ? i : 0);
      grid[r][c] = { ch: e.word[i], value: "", hinted: false };
    }
  }
  // 번호: 위에서 아래, 왼쪽에서 오른쪽 순서. 같은 칸에서 시작하면 번호를 같이 쓴다.
  const starts = [...new Set(entries.map((e) => `${e.r},${e.c}`))].map((k) => k.split(",").map(Number)).sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  starts.forEach(([r, c], i) => (grid[r][c].num = i + 1));
  for (const e of entries) e.num = grid[e.r][e.c].num;
  entries.sort((a, b) => a.num - b.num);
  return { levelId, rows, cols, grid, entries, done: false, revealed: false };
}

function entryCells(e) {
  return Array.from({ length: e.word.length }, (_, i) => [e.r + (e.dir === "down" ? i : 0), e.c + (e.dir === "across" ? i : 0)]);
}

function entrySolved(puzzle, e) {
  return entryCells(e).every(([r, c]) => puzzle.grid[r][c].value === puzzle.grid[r][c].ch);
}

function renderCrosswordListScreen(root, { profileName, start, back }) {
  const myLevel = getPreferredLevel(profileName) || getLastWordLevel(profileName);
  root.innerHTML = `
    <div class="screen screen-crossword">
      <button class="back-btn" id="backBtn">← 홈</button>
      <h1 class="title">🧩 가로세로 낱말 퀴즈</h1>
      <p class="subtitle">할 때마다 새로운 퍼즐이 만들어져요</p>
      <section class="lesson-section">
        <p class="lesson-point-text">단계를 고르면 그 단계 단어장에서 단어를 무작위로 뽑아 퍼즐을 만들어요. 힌트(한국어 뜻)를 보고 영어 철자를 칸에 써요. 칸이나 힌트를 누르면 그 단어가 선택되고, 같은 칸을 한 번 더 누르면 가로 ↔ 세로가 바뀌어요.</p>
      </section>
      ${(() => {
        const card = (lv) => {
          const best = getSectionBest(profileName, "crossword", lv.id);
          return `
          <button class="level-card" data-level="${lv.id}" style="--accent:${lv.color}">
            <span class="level-icon">${lv.emoji}</span>
            <span class="topic-text">
              <span class="level-label">${lv.label}${lv.id === myLevel ? " · 내 단계" : ""}</span>
              <span class="topic-summary">단어 ${crosswordPool(lv.id).length}개 중에서 무작위</span>
            </span>
            <span class="level-best${best ? "" : " level-best-empty"}">${ratioLabel(best)}</span>
          </button>`;
        };
        const { mine, others } = splitByMyLevel(LEVELS, (lv) => [lv.id], myLevel);
        return levelSplitHtml(mine.map(card).join(""), others.map(card).join(""), others.length);
      })()}
    </div>
  `;
  root.querySelector("#backBtn").addEventListener("click", back);
  root.querySelectorAll("[data-level]").forEach((btn) => btn.addEventListener("click", () => start(btn.dataset.level)));
}

function renderCrosswordScreen(root, { puzzle, actions }) {
  const level = levelById(puzzle.levelId);
  let sel = puzzle.sel || { r: puzzle.entries[0].r, c: puzzle.entries[0].c, dir: puzzle.entries[0].dir };
  const solvedCount = () => puzzle.entries.filter((e) => entrySolved(puzzle, e)).length;
  const cellSize = `min(38px, calc((100vw - 48px) / ${puzzle.cols}))`;

  const entryAt = (r, c, dir) => puzzle.entries.find((e) => e.dir === dir && entryCells(e).some(([rr, cc]) => rr === r && cc === c));
  const currentEntry = () => entryAt(sel.r, sel.c, sel.dir) || entryAt(sel.r, sel.c, sel.dir === "across" ? "down" : "across");

  root.innerHTML = `
    <div class="screen screen-crossword-play"${levelThemeStyle(level)}>
      <div class="cw-top">
        <button class="back-btn" id="quitBtn">× 그만하기</button>
        <span class="cw-progress" id="cwProgress"></span>
      </div>
      <div class="cw-clue-bar" id="clueBar" aria-live="polite"></div>
      <div class="cw-grid" style="grid-template-columns:repeat(${puzzle.cols}, ${cellSize});grid-auto-rows:${cellSize}">
        ${puzzle.grid
          .map((row, r) =>
            row
              .map((cell, c) =>
                cell
                  ? `<div class="cw-cell" data-r="${r}" data-c="${c}">${cell.num ? `<span class="cw-num">${cell.num}</span>` : ""}<input class="cw-input" data-r="${r}" data-c="${c}" autocomplete="off" autocapitalize="characters" spellcheck="false" inputmode="text" lang="en" aria-label="${r + 1}행 ${c + 1}열" value="${cell.value.toUpperCase()}" ${puzzle.done ? "disabled" : ""}/></div>`
                  : `<div class="cw-empty"></div>`
              )
              .join("")
          )
          .join("")}
      </div>
      <div class="cw-actions">
        ${puzzle.done ? "" : `<button class="secondary-btn" id="hintBtn">💡 한 글자</button><button class="secondary-btn" id="revealBtn">🏳️ 정답 보기</button>`}
        <button class="primary-btn" id="newBtn">🔄 새 퍼즐</button>
      </div>
      <div class="cw-clues">
        ${["across", "down"]
          .map(
            (dir) => `
          <section>
            <h2 class="section-title">${dir === "across" ? "가로 →" : "세로 ↓"}</h2>
            <ol class="cw-clue-list">
              ${puzzle.entries
                .filter((e) => e.dir === dir)
                .map((e) => `<li><button class="cw-clue" data-num="${e.num}" data-dir="${dir}"><b>${e.num}</b> ${e.data.emoji || ""} ${e.data.meaningKo} <small>(${e.word.length}글자)</small></button></li>`)
                .join("")}
            </ol>
          </section>`
          )
          .join("")}
      </div>
    </div>
  `;

  const input = (r, c) => root.querySelector(`.cw-input[data-r="${r}"][data-c="${c}"]`);

  const paint = () => {
    const cur = currentEntry();
    const curCells = new Set(cur ? entryCells(cur).map(([r, c]) => `${r},${c}`) : []);
    const solvedCells = new Set(puzzle.entries.filter((e) => entrySolved(puzzle, e)).flatMap((e) => entryCells(e).map(([r, c]) => `${r},${c}`)));
    root.querySelectorAll(".cw-cell").forEach((el) => {
      const k = `${el.dataset.r},${el.dataset.c}`;
      const cell = puzzle.grid[el.dataset.r][el.dataset.c];
      el.classList.toggle("in-word", curCells.has(k));
      el.classList.toggle("active", k === `${sel.r},${sel.c}`);
      el.classList.toggle("solved", solvedCells.has(k));
      el.classList.toggle("hinted", cell.hinted);
      el.classList.toggle("wrong", puzzle.revealed && cell.value !== cell.ch);
    });
    root.querySelectorAll(".cw-clue").forEach((b) => {
      const e = puzzle.entries.find((x) => x.num === Number(b.dataset.num) && x.dir === b.dataset.dir);
      b.classList.toggle("current", e === cur);
      b.classList.toggle("solved", entrySolved(puzzle, e));
    });
    root.querySelector("#clueBar").innerHTML = puzzle.done
      ? puzzle.revealed
        ? "📖 정답을 확인하고 새 퍼즐에 도전해요!"
        : "🎉 퍼즐 완성!"
      : cur
        ? `<b>${cur.num} ${cur.dir === "across" ? "가로" : "세로"}</b> · ${cur.data.meaningKo} <small>(${cur.word.length}글자)</small>`
        : "";
    root.querySelector("#cwProgress").textContent = `${solvedCount()} / ${puzzle.entries.length} 단어`;
  };

  const select = (r, c, dir, focus = true) => {
    sel = { r, c, dir };
    if (!entryAt(r, c, dir)) sel.dir = dir === "across" ? "down" : "across";
    puzzle.sel = sel;
    paint();
    if (focus && !puzzle.done) input(r, c)?.focus({ preventScroll: false });
  };

  const step = (delta) => {
    const cur = currentEntry();
    if (!cur) return;
    const cells = entryCells(cur);
    const i = cells.findIndex(([r, c]) => r === sel.r && c === sel.c);
    const next = cells[i + delta];
    if (next) select(next[0], next[1], cur.dir);
  };

  const checkDone = () => {
    if (puzzle.grid.every((row) => row.every((cell) => !cell || cell.value === cell.ch))) {
      puzzle.done = true;
      actions.finish(puzzle);
    }
  };

  root.querySelectorAll(".cw-input").forEach((el) => {
    const r = Number(el.dataset.r);
    const c = Number(el.dataset.c);
    el.addEventListener("pointerdown", () => {
      if (sel.r === r && sel.c === c) select(r, c, sel.dir === "across" ? "down" : "across", false);
      else select(r, c, sel.dir, false);
    });
    el.addEventListener("focus", () => {
      if (sel.r !== r || sel.c !== c) select(r, c, sel.dir, false);
      // 이미 글자가 있어도 새로 치면 바뀌도록 전체 선택
      setTimeout(() => el.select(), 0);
    });
    el.addEventListener("input", () => {
      // 입력이 들어온 칸에서 시작한다 (선택 상태가 어긋나 있어도)
      if (sel.r !== r || sel.c !== c) {
        sel = { r, c, dir: entryAt(r, c, sel.dir) ? sel.dir : sel.dir === "across" ? "down" : "across" };
        puzzle.sel = sel;
      }
      const old = puzzle.grid[r][c].value;
      let letters = (el.value.match(/[a-z]/gi) || []).map((x) => x.toLowerCase());
      // 선택이 풀린 채로 덧붙여 친 경우(예: "a" 뒤에 "b")에는 새 글자만 쓴다
      if (letters.length === 2 && letters[0] === old) letters = letters.slice(1);
      if (!letters.length) {
        el.value = "";
        puzzle.grid[r][c].value = "";
        paint();
        return;
      }
      // 여러 글자가 한꺼번에 들어오면(붙여넣기 · 빠른 입력) 다음 칸으로 차례로 채운다
      for (const ch of letters) {
        const target = input(sel.r, sel.c);
        if (!target || target.disabled) break;
        target.value = ch.toUpperCase();
        puzzle.grid[sel.r][sel.c].value = ch;
        recordActivityThrottled();
        const before = `${sel.r},${sel.c}`;
        step(1);
        if (`${sel.r},${sel.c}` === before) break; // 단어 끝
      }
      paint();
      checkDone();
    });
    el.addEventListener("keydown", (e) => {
      if (e.key === "Backspace" && !el.value) {
        e.preventDefault();
        if (sel.r !== r || sel.c !== c) {
          sel = { r, c, dir: sel.dir };
          puzzle.sel = sel;
        }
        step(-1);
        const prev = input(sel.r, sel.c);
        if (prev) {
          prev.value = "";
          puzzle.grid[sel.r][sel.c].value = "";
          paint();
        }
      } else if (e.key.startsWith("Arrow")) {
        e.preventDefault();
        const d = { ArrowRight: [0, 1, "across"], ArrowLeft: [0, -1, "across"], ArrowDown: [1, 0, "down"], ArrowUp: [-1, 0, "down"] }[e.key];
        const nr = r + d[0];
        const nc = c + d[1];
        if (puzzle.grid[nr]?.[nc]) select(nr, nc, d[2]);
      }
    });
  });

  root.querySelectorAll(".cw-clue").forEach((b) =>
    b.addEventListener("click", () => {
      const e = puzzle.entries.find((x) => x.num === Number(b.dataset.num) && x.dir === b.dataset.dir);
      const firstEmpty = entryCells(e).find(([r, c]) => puzzle.grid[r][c].value !== puzzle.grid[r][c].ch) || [e.r, e.c];
      select(firstEmpty[0], firstEmpty[1], e.dir);
      root.querySelector(".cw-grid").scrollIntoView({ behavior: "smooth", block: "nearest" });
    })
  );

  root.querySelector("#hintBtn")?.addEventListener("click", () => {
    const cur = currentEntry();
    const target = cur && entryCells(cur).find(([r, c]) => puzzle.grid[r][c].value !== puzzle.grid[r][c].ch);
    if (!target) return;
    const [r, c] = target;
    const cell = puzzle.grid[r][c];
    cell.value = cell.ch;
    cell.hinted = true;
    input(r, c).value = cell.ch.toUpperCase();
    select(r, c, cur.dir);
    step(1);
    checkDone();
  });
  root.querySelector("#revealBtn")?.addEventListener("click", () =>
    showConfirmModal({
      message: "정답을 모두 보여 줄까요? 이번 퍼즐은 여기서 끝나요.",
      confirmText: "정답 보기",
      cancelText: "계속 풀기",
      onConfirm: () => {
        puzzle.revealed = true;
        puzzle.done = true;
        actions.finish(puzzle);
      },
    })
  );
  root.querySelector("#newBtn").addEventListener("click", () => actions.newPuzzle(puzzle.levelId));
  root.querySelector("#quitBtn").addEventListener("click", actions.quit);

  paint();
  if (puzzle.done) {
    puzzle.grid.forEach((row, r) =>
      row.forEach((cell, c) => {
        if (cell && puzzle.revealed) input(r, c).value = cell.ch.toUpperCase();
      })
    );
    paint();
  }
}

// 글자를 쓸 때마다 기록하면 너무 많아서, 단어 하나쯤(5글자)에 한 번 학습 기록을 남긴다.
let crosswordTyped = 0;
function recordActivityThrottled() {
  crosswordTyped += 1;
  if (crosswordTyped % 5 === 0) recordActivity(store.getState().profileName);
}

;

