// 개근 선물: 한 달 개근을 perfect번 하면 공짜로 받는다
// 어드벤트 선물: 크리스마스 도장을 advent개 모으면 공짜로 받는다
function shopItemUnlocked(profileName, item) {
  const p = getProfileData(profileName);
  if (item.advent) return p.advent.length >= item.advent;
  if (item.tier) return p.totalAnswered >= (PET_TIERS.find((t) => t.id === item.tier)?.min ?? Infinity);
  if (item.bond) return bondLevelIndex(p.care.bond) >= item.bond;
  return !item.perfect || p.perfectMonths.length >= item.perfect;
}

function shopLockLabel(it) {
  if (it.advent) return `🎄 도장 ${it.advent}개`;
  if (it.tier) {
    const t = PET_TIERS.find((x) => x.id === it.tier);
    return `${t.icon} ${t.name} 등급`;
  }
  if (it.bond) return `❤️ ${BOND_LEVELS[it.bond].name}`;
  return `📆 개근 ${it.perfect}번`;
}

function shopItem(id) {
  return SHOP_ITEMS.find((it) => it.id === id) || null;
}

function shopStatus(profileName) {
  const p = getProfileData(profileName);
  const earned = Math.floor(p.totalAnswered / STAR_EVERY) + p.bonusStars;
  return { earned, stars: Math.max(0, earned - p.shop.spent), owned: p.shop.owned, equip: p.shop.equip, toNext: STAR_EVERY - (p.totalAnswered % STAR_EVERY) };
}

// 꾸민 캐릭터: 머리 · 얼굴 · 목 · 손 아이템 + 캐릭터 + 함께 다니는 친구 + 반짝 효과
function dressedPetHtml(profileName, petEmoji, big, scale = 1) {
  const { equip } = shopStatus(profileName);
  const on = (cat, cls) => {
    const it = shopItem(equip[cat]);
    return it ? `<span class="${cls}" aria-hidden="true">${it.emoji}</span>` : "";
  };
  return `<span class="pet-avatar${big ? " big" : ""}">${on("fx", "pet-fx")}<span class="pet-body"${scale !== 1 ? ` style="transform:scale(${scale});transform-origin:bottom center"` : ""}>${on("hat", "pet-hat")}<span class="pet-emoji" aria-hidden="true">${petEmoji}</span>${on("face", "pet-face")}${on("neck", "pet-neck")}${on("hand", "pet-hand")}</span>${on("pal", "pet-pal")}</span>`;
}

function petBackgroundStyle(profileName) {
  const bg = shopItem(shopStatus(profileName).equip.bg);
  return bg ? { cls: " pet-themed", style: ` style="background:${bg.bg}"` } : { cls: "", style: "" };
}

function renderShopScreen(root, { profileName, actions }) {
  const s = shopStatus(profileName);
  const pet = petStatus(profileName);
  const theme = petBackgroundStyle(profileName);
  root.innerHTML = `
    <div class="screen screen-shop">
      <button class="back-btn" id="backBtn">← 홈</button>
      <h1 class="title">⭐ 별 상점</h1>
      <p class="subtitle">문제를 ${STAR_EVERY}개 풀 때마다 ⭐ 1개 · 다음 별까지 ${s.toNext}문제</p>
      <section class="pet-big${theme.cls}"${theme.style}>
        <span class="pet-aura-wrap${pet.aura}">${dressedPetHtml(profileName, pet.stage.emoji, true, pet.stage.scale)}</span>
        <p class="shop-stars">⭐ <b>${s.stars}</b>개 있어요</p>
      </section>
      ${SHOP_CATS.map(
        (cat) => `
        <h2 class="section-title">${cat.title}</h2>
        <div class="shop-grid">
          ${SHOP_ITEMS.filter((it) => it.cat === cat.id)
            .map((it) => {
              const owned = s.owned.includes(it.id);
              const on = s.equip[cat.id] === it.id;
              const unlocked = shopItemUnlocked(profileName, it);
              const label = on ? "벗기" : owned ? "꾸미기" : !unlocked ? shopLockLabel(it) : it.price ? `⭐ ${it.price}` : "🎁 받기";
              return `<button class="shop-item${on ? " on" : ""}${owned ? " owned" : ""}" data-item="${it.id}" ${!owned && (!unlocked || s.stars < it.price) ? "disabled" : ""}>
                <span class="shop-emoji"${it.bg ? ` style="background:${it.bg}"` : ""}>${it.emoji}</span>
                <b>${it.name}</b>
                <small>${label}</small>
              </button>`;
            })
            .join("")}
        </div>`
      ).join("")}
    </div>`;
  root.querySelector("#backBtn").addEventListener("click", actions.back);
  root.querySelectorAll("[data-item]").forEach((b) => b.addEventListener("click", () => actions.tap(b.dataset.item)));
}

;

/* ── js/screens/moreGames.js ── */
// 🐍 영어 끝말잇기 · 🎱 단어 빙고 · 📆 출석 달력 · 🖨️ 인쇄용 단어 시험지

// ── 🐍 영어 끝말잇기: 앞 단어의 마지막 글자로 시작하는 단어를 이어 간다 ──
const CHAIN_LIVES = 3;
let chainByLetter = null;

// 첫 글자별 단어 목록 (한 단어 · 세 글자 이상)
function chainWords(letter) {
  if (!chainByLetter) {
    chainByLetter = {};
    for (const lv of LEVELS) {
      for (const w of WORD_BANK[lv.id] || []) {
        if (!/^[a-z]{3,}$/.test(w.word)) continue;
        (chainByLetter[w.word[0]] ||= []).push({ w, levelId: lv.id });
      }
    }
  }
  return chainByLetter[letter] || [];
}

// 내 단계와 가까운 단어부터
function chainByCloseness(list, levelId) {
  const my = LEVELS.findIndex((lv) => lv.id === levelId);
  const dist = (x) => Math.abs(LEVELS.findIndex((lv) => lv.id === x.levelId) - my);
  return shuffle(list).sort((a, b) => dist(a) - dist(b));
}

const chainLast = (game) => game.history[game.history.length - 1].w.word;
const chainNeed = (game) => chainLast(game).slice(-1);

function chainOptions(game) {
  const need = chainNeed(game);
  const valid = chainByCloseness(chainWords(need).filter((x) => !game.used.includes(x.w.word)), game.levelId).slice(0, 2);
  const letters = "abcdefghijklmnoprstw".split("").filter((l) => l !== need);
  const wrong = [];
  for (const l of shuffle(letters)) {
    const pick = chainByCloseness(chainWords(l).filter((x) => !game.used.includes(x.w.word)), game.levelId)[0];
    if (pick) wrong.push(pick);
    if (wrong.length === 4 - valid.length) break;
  }
  return shuffle([...valid, ...wrong]).map((x) => ({ ...x, ok: x.w.word[0] === need, hidden: false, wrong: false }));
}

function newWordChain(levelId) {
  // 컴퓨터가 내 단계 단어로 시작한다 (다음 글자로 시작하는 단어가 넉넉한 것으로)
  const pool = (WORD_BANK[levelId] || []).filter((w) => /^[a-z]{3,}$/.test(w.word)).map((w) => ({ w, levelId }));
  const start = shuffle(pool).find((x) => chainWords(x.w.word.slice(-1)).length > 5) || chainWords("a")[0];
  const game = { levelId, used: [start.w.word], history: [{ who: "cpu", ...start }], lives: CHAIN_LIVES, turns: 0, hintUsed: false, options: [], done: false, result: null, isNewBest: false, message: "" };
  game.options = chainOptions(game);
  return game;
}

// 컴퓨터 차례: 이을 단어가 없거나, 오래 이어지면 가끔 "모르겠어요!" 하고 진다
function chainComputerMove(game) {
  const need = chainNeed(game);
  const cands = chainByCloseness(chainWords(need).filter((x) => !game.used.includes(x.w.word)), game.levelId);
  const giveUp = cands.length === 0 || (game.turns >= 6 && Math.random() < 0.12 + game.turns * 0.01);
  if (giveUp) return null;
  // 사람이 이을 단어가 있는 글자로 끝나는 단어를 고른다
  return cands.find((x) => chainWords(x.w.word.slice(-1)).some((y) => !game.used.includes(y.w.word) && y.w.word !== x.w.word)) || null;
}

